import{_ as r,o as e,c as a,ag as n}from"./chunks/framework.BJFNwp4n.js";const u=JSON.parse('{"title":"Module 6: Consolidation and Personalisation","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/modules/maltese-module6-analysis.md","filePath":"en/more/maltese/modules/maltese-module6-analysis.md"}'),o={name:"en/more/maltese/modules/maltese-module6-analysis.md"};function s(i,t,l,g,d,h){return e(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794416186000"},[...t[0]||(t[0]=[n('<h1 id="module-6-consolidation-and-personalisation" tabindex="-1">Module 6: Consolidation and Personalisation <a class="header-anchor" href="#module-6-consolidation-and-personalisation" aria-label="Permalink to &quot;Module 6: Consolidation and Personalisation&quot;">​</a></h1><h2 id="cover-page-breakdown" tabindex="-1">Cover Page Breakdown <a class="header-anchor" href="#cover-page-breakdown" aria-label="Permalink to &quot;Cover Page Breakdown&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Original</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>MQF 2 – Maltese Language and Cultural Orientation for Foreigners</td><td>MQF Level 2: Maltese language and cultural orientation for foreigners.<br><strong>MQF 2</strong> a qualification level, not &quot;second module&quot;<br><strong>Maltese Language</strong> the Maltese language<br><strong>Cultural Orientation</strong> cultural orientation / introduction<br><strong>for Foreigners</strong> for foreigners.</td></tr><tr><td>Module 6 / Consolidation and Personalisation</td><td>Module 6: consolidation and personalisation.<br><strong>Module 6</strong> module 6<br><strong>Consolidation</strong> consolidating what has been learnt<br><strong>and</strong> and<br><strong>Personalisation</strong> applying it to one&#39;s own situation. The cover is in English, so no invented Maltese title is presented as the original.</td></tr></tbody></table><hr><h2 id="_1-the-seven-oral-topics-and-their-tenses" tabindex="-1">1 The Seven Oral Topics and Their Tenses <a class="header-anchor" href="#_1-the-seven-oral-topics-and-their-tenses" aria-label="Permalink to &quot;1 The Seven Oral Topics and Their Tenses&quot;">​</a></h2><h3 id="the-topics-and-the-tense-to-use" tabindex="-1">The topics and the tense to use <a class="header-anchor" href="#the-topics-and-the-tense-to-use" aria-label="Permalink to &quot;The topics and the tense to use&quot;">​</a></h3><p><code>It-Taħdit</code> = speaking. <code>B’liema temp se titkellem dwar dawn it-temi?</code> = which tense will you speak in about these topics?</p><p><strong>B’liema</strong> with which<br><strong>temp</strong> here the grammatical tense, not the weather<br><strong>se titkellem</strong> you will speak<br><strong>dwar</strong> about<br><strong>dawn it-temi</strong> these topics<br><strong>Passat</strong> past tense<br><strong>Preżent</strong> present tense<br><strong>Futur</strong> future tense.</p><table tabindex="0"><thead><tr><th>Topic and every prompt</th><th>Chinese, words and tense</th></tr></thead><tbody><tr><td>1. Jien: iddeskrivi lilek innifsek, xi tgħid dwarek u dwar ħajtek? X’edukazzjoni għandek? X’taħdem? (Xogħol) X’inhuma l-passatempi tiegħek?</td><td>Introduce yourself, mainly in the present; finished education may take the past.<br><strong>Jien</strong> I<br><strong>iddeskrivi</strong> describe<br><strong>lilek innifsek</strong> yourself<br><strong>xi tgħid</strong> what you say<br><strong>dwarek</strong> about you<br><strong>u dwar ħajtek</strong> and about your life<br><strong>X’edukazzjoni għandek</strong> what education you have<br><strong>X’taħdem / Xogħol</strong> what work you do / work<br><strong>X’inhuma</strong> what they are<br><strong>l-passatempi tiegħek</strong> your hobbies.</td></tr><tr><td>2. Il-familja: min huma l-membri tal-familja tiegħek? X’jisimhom? Fejn jgħixu? Xi tgħid fuqhom?</td><td>The family, usually in the present.<br><strong>Il-familja</strong> the family<br><strong>min huma</strong> who they are<br><strong>l-membri</strong> the members<br><strong>tal-familja tiegħek</strong> of your family<br><strong>X’jisimhom</strong> what they are called, -hom = them<br><strong>Fejn jgħixu</strong> where they live<br><strong>Xi tgħid fuqhom</strong> what you say about them, fuqhom = about them.</td></tr><tr><td>3. Il-pjanijiet: x’se tagħmel fil-futur? Qed tippjana xi safra? Xi avveniment speċjali? X’se jiġri?</td><td>Plans: future tense; something being planned now can use qed.<br><strong>Il-pjanijiet</strong> the plans, plural<br><strong>x’se tagħmel</strong> what you will do<br><strong>fil-futur</strong> in the future<br><strong>Qed tippjana</strong> you are planning<br><strong>xi safra</strong> some trip<br><strong>xi avveniment speċjali</strong> some special event<br><strong>X’se jiġri</strong> what will happen.</td></tr><tr><td>4. L-ikel: liema hu l-ikel favorit tiegħek? Hemm xi ħaġa li żgur ma tikolx? Tħobb issajjar?</td><td>Food: habits and preferences take the present.<br><strong>L-ikel</strong> food<br><strong>liema hu</strong> which one is<br><strong>l-ikel favorit tiegħek</strong> your favourite food<br><strong>Hemm xi ħaġa</strong> is there anything<br><strong>li żgur ma tikolx</strong> that you certainly do not eat<br><strong>Tħobb issajjar</strong> do you like cooking.</td></tr><tr><td>5. Id-divertiment: kif tħobb tiddeverti? Fejn tmur u ma’ min?</td><td>Entertainment: usually the present.<br><strong>Id-divertiment</strong> entertainment<br><strong>kif tħobb tiddeverti</strong> how you like to enjoy yourself<br><strong>Fejn tmur</strong> where you go<br><strong>u ma’ min</strong> and with whom.</td></tr><tr><td>6. It-trasport: X’mezzi ta’ trasport tuża? Liema tippreferi? Liema jdejqek?</td><td>Transport: daily habits take the present.<br><strong>It-trasport</strong> transport<br><strong>X’mezzi ta’ trasport</strong> which means of transport<br><strong>tuża</strong> you use<br><strong>Liema tippreferi</strong> which one you prefer<br><strong>Liema jdejqek</strong> which one bothers you, -ek = you.</td></tr><tr><td>7. L-ivvjaġġar / is-safar: Tħobb issiefer? Liema pajjiżi ġieli żort? Liema l-iktar li għoġbok u għaliex? Hemm xi pajjiż li ma jogħġbokx? Iddeskrivi safra li għamilt.</td><td>Travel: preferences in the present, past experiences in the past.<br><strong>L-ivvjaġġar / is-safar</strong> travel, travelling abroad<br><strong>Tħobb issiefer</strong> do you like travelling<br><strong>Liema pajjiżi</strong> which countries<br><strong>ġieli żort</strong> you have sometimes visited<br><strong>Liema l-iktar li għoġbok</strong> which one you liked most<br><strong>u għaliex</strong> and why<br><strong>Hemm xi pajjiż</strong> is there some country<br><strong>li ma jogħġbokx</strong> that you do not like<br><strong>Iddeskrivi safra</strong> describe a trip<br><strong>li għamilt</strong> that you took.</td></tr></tbody></table><h3 id="seven-fuller-model-answers-line-by-line" tabindex="-1">Seven fuller model answers, line by line <a class="header-anchor" href="#seven-fuller-model-answers-line-by-line" aria-label="Permalink to &quot;Seven fuller model answers, line by line&quot;">​</a></h3><p>Each group read in sequence forms a short spoken turn; Alex is a fictional person. Male adjective forms can be changed to feminine as needed.</p><table tabindex="0"><thead><tr><th>Topic and answer sentence</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1a. Jisimni Alex, għandi tletin sena u noqgħod l-Imsida ma’ ħabib tiegħi.</td><td>My name is Alex, I am 30, and I live in Msida with my friend.<br><strong>Jisimni</strong> I am called<br><strong>Alex</strong> a fictional name<br><strong>għandi tletin sena</strong> I am thirty years old<br><strong>u noqgħod</strong> and I live<br><strong>l-Imsida</strong> in Msida<br><strong>ma’ ħabib tiegħi</strong> with my friend.</td></tr><tr><td>1b. Studjajt l-informatika u issa naħdem f’uffiċċju żgħir fil-Belt.</td><td>I studied computing and now I work in a small office in Valletta.<br><strong>Studjajt</strong> I studied<br><strong>l-informatika</strong> computing / information technology<br><strong>u issa</strong> and now<br><strong>naħdem</strong> I work<br><strong>f’uffiċċju żgħir</strong> in a small office<br><strong>fil-Belt</strong> in Valletta, the usual name for the capital.</td></tr><tr><td>1c. Fil-ħin liberu nħobb naqra, insajjar u nimxi ħdejn il-baħar biex nistrieħ.</td><td>In my free time I like reading, cooking and walking by the sea to rest.<br><strong>Fil-ħin liberu</strong> in free time<br><strong>nħobb</strong> I like<br><strong>naqra</strong> reading<br><strong>insajjar</strong> cooking<br><strong>u nimxi ħdejn il-baħar</strong> and walking by the sea<br><strong>biex nistrieħ</strong> in order to rest.</td></tr><tr><td>2a. Il-familja tiegħi tinkludi lil ommi Maria, missieri Paul u oħti Anna.</td><td>My family includes my mother Maria, my father Paul and my sister Anna.<br><strong>Il-familja tiegħi</strong> my family<br><strong>tinkludi</strong> includes<br><strong>lil ommi Maria</strong> my mother Maria<br><strong>missieri Paul</strong> my father Paul<br><strong>u oħti Anna</strong> and my sister Anna.</td></tr><tr><td>2b. Huma jgħixu barra minn Malta, iżda nitkellmu fuq it-telefon kważi kuljum.</td><td>They live outside Malta, but we talk on the phone almost every day.<br><strong>Huma</strong> they<br><strong>jgħixu</strong> live<br><strong>barra minn Malta</strong> outside Malta<br><strong>iżda</strong> but<br><strong>nitkellmu</strong> we talk<br><strong>fuq it-telefon</strong> on the phone<br><strong>kważi kuljum</strong> almost every day.</td></tr><tr><td>2c. Ommi tħobb issajjar, missieri jħobb il-ġnien, u oħti għadha tistudja.</td><td>My mother likes cooking, my father likes gardening, and my sister is still studying.<br><strong>Ommi tħobb issajjar</strong> my mother likes cooking<br><strong>missieri jħobb il-ġnien</strong> my father likes the garden<br><strong>u oħti</strong> and my sister<br><strong>għadha tistudja</strong> she is still studying, -ha = she.</td></tr><tr><td>3a. Fil-futur se nkompli nistudja l-Malti għax nixtieq nitkellem aħjar mal-ġirien.</td><td>In the future I will keep studying Maltese because I want to talk better with the neighbours.<br><strong>Fil-futur</strong> in the future<br><strong>se nkompli</strong> I will continue<br><strong>nistudja l-Malti</strong> studying Maltese<br><strong>għax nixtieq</strong> because I want<br><strong>nitkellem aħjar</strong> to speak better<br><strong>mal-ġirien</strong> with the neighbours.</td></tr><tr><td>3b. Qed nippjana safra lejn l-Italja f’Settembru ma’ żewġ ħbieb tal-kors.</td><td>I am planning a trip to Italy in September with two friends from the course.<br><strong>Qed nippjana</strong> I am planning<br><strong>safra lejn l-Italja</strong> a trip to Italy<br><strong>f’Settembru</strong> in September<br><strong>ma’ żewġ ħbieb tal-kors</strong> with two course friends.</td></tr><tr><td>3c. Se niċċelebraw għeluq snin ħabib tagħna u se nqattgħu ġimgħa hemmhekk.</td><td>We will celebrate our friend&#39;s birthday and will spend a week there.<br><strong>Se niċċelebraw</strong> we will celebrate<br><strong>għeluq snin</strong> birthday<br><strong>ħabib tagħna</strong> our friend<br><strong>u se nqattgħu</strong> and we will spend<br><strong>ġimgħa hemmhekk</strong> a week there.</td></tr><tr><td>4a. L-ikel favorit tiegħi huwa l-għaġin bil-ħaxix, speċjalment meta nsajru d-dar.</td><td>My favourite food is pasta with vegetables, especially when it is made at home.<br><strong>L-ikel favorit tiegħi</strong> my favourite food<br><strong>huwa l-għaġin bil-ħaxix</strong> is pasta with vegetables<br><strong>speċjalment</strong> especially<br><strong>meta nsajru</strong> when it is cooked, -u refers to għaġin and may also read &quot;we cook it&quot; in context<br><strong>d-dar</strong> at home.</td></tr><tr><td>4b. Żgur ma niekolx ikel li jien allerġiku għalih, u dejjem naqra l-ingredjenti.</td><td>I certainly do not eat food I am allergic to, and I always read the ingredients.<br><strong>Żgur</strong> certainly<br><strong>ma niekolx</strong> I do not eat<br><strong>ikel</strong> food<br><strong>li jien allerġiku għalih</strong> to which I am allergic, għalih = to it<br><strong>u dejjem naqra</strong> and I always read<br><strong>l-ingredjenti</strong> the ingredients.</td></tr><tr><td>4c. Inħobb insajjar fi tmiem il-ġimgħa għax ikolli aktar ħin nipprova riċetti ġodda.</td><td>I like cooking at the weekend because I have more time to try new recipes.<br><strong>Inħobb insajjar</strong> I like cooking<br><strong>fi tmiem il-ġimgħa</strong> at the weekend<br><strong>għax ikolli</strong> because I will have<br><strong>aktar ħin</strong> more time<br><strong>nipprova</strong> I try<br><strong>riċetti ġodda</strong> new recipes.</td></tr><tr><td>5a. Biex niddeverti nħobb niltaqa’ ma’ sħabi, nara film jew immur mixja twila.</td><td>To enjoy myself I like meeting friends, watching a film or going on a long walk.<br><strong>Biex niddeverti</strong> in order to enjoy myself<br><strong>nħobb niltaqa’</strong> I like to meet<br><strong>ma’ sħabi</strong> with my friends<br><strong>nara film</strong> I watch a film<br><strong>jew immur mixja twila</strong> or go on a long walk.</td></tr><tr><td>5b. Normalment immorru l-Belt is-Sibt filgħaxija u nieklu xi ħaġa wara l-film.</td><td>We usually go to Valletta on Saturday evening and eat something after the film.<br><strong>Normalment</strong> usually<br><strong>immorru l-Belt</strong> we go to Valletta<br><strong>is-Sibt filgħaxija</strong> on Saturday evening<br><strong>u nieklu xi ħaġa</strong> and we eat something<br><strong>wara l-film</strong> after the film.</td></tr><tr><td>5c. Meta nkun għajjien nippreferi noqgħod id-dar u naqra ktieb bil-kwiet.</td><td>When I am tired I prefer to stay at home and read a book quietly.<br><strong>Meta nkun għajjien</strong> when I am tired, masculine form<br><strong>nippreferi</strong> I prefer<br><strong>noqgħod id-dar</strong> I stay at home<br><strong>u naqra ktieb</strong> and I read a book<br><strong>bil-kwiet</strong> quietly.</td></tr><tr><td>6a. Nuża l-karozza tal-linja biex immur għax-xogħol, iżda għal postijiet qrib nimxi.</td><td>I use the bus to go to work, but for nearby places I walk.<br><strong>Nuża</strong> I use<br><strong>l-karozza tal-linja</strong> the bus<br><strong>biex immur għax-xogħol</strong> in order to go to work<br><strong>iżda</strong> but<br><strong>għal postijiet qrib</strong> for nearby places<br><strong>nimxi</strong> I walk.</td></tr><tr><td>6b. Nippreferi l-ferrovija meta nsiefer għax nista’ naqra u nara l-veduta matul il-vjaġġ.</td><td>I prefer the train when travelling abroad because I can read and see the view during the journey.<br><strong>Nippreferi l-ferrovija</strong> I prefer the train<br><strong>meta nsiefer</strong> when I travel abroad<br><strong>għax nista’ naqra</strong> because I can read<br><strong>u nara l-veduta</strong> and see the view<br><strong>matul il-vjaġġ</strong> during the journey.</td></tr><tr><td>6c. It-traffiku jdejjaqni, speċjalment meta jkolli nistenna ħafna biex nasal id-dar.</td><td>Traffic bothers me, especially when I have to wait a long time to get home.<br><strong>It-traffiku</strong> the traffic<br><strong>jdejjaqni</strong> it bothers me<br><strong>speċjalment meta</strong> especially when<br><strong>jkolli nistenna ħafna</strong> I have to wait a long time<br><strong>biex nasal id-dar</strong> in order to get home.</td></tr><tr><td>7a. Inħobb insiefer u diġà żort l-Italja u Spanja matul il-vaganzi tiegħi.</td><td>I like travelling abroad and have already visited Italy and Spain during my holidays.<br><strong>Inħobb insiefer</strong> I like travelling abroad<br><strong>u diġà żort</strong> and I have already visited<br><strong>l-Italja u Spanja</strong> Italy and Spain<br><strong>matul il-vaganzi tiegħi</strong> during my holidays.</td></tr><tr><td>7b. L-iktar pajjiż li għoġobni kien l-Italja minħabba l-arti, l-ikel u l-bliet antiki.</td><td>The country I liked most was Italy, because of the art, the food and the old cities.<br><strong>L-iktar pajjiż li għoġobni</strong> the country I liked most<br><strong>kien l-Italja</strong> was Italy<br><strong>minħabba</strong> because of<br><strong>l-arti</strong> the art<br><strong>l-ikel</strong> the food<br><strong>u l-bliet antiki</strong> and the old cities.</td></tr><tr><td>7c. M’hemmx pajjiż li nista’ ngħid li ma jogħġobnix, għax għad hemm ħafna x’niskopri.</td><td>There is no country I can say I do not like, because there is still much to discover.<br><strong>M’hemmx pajjiż</strong> there is no country<br><strong>li nista’ ngħid</strong> that I can say<br><strong>li ma jogħġobnix</strong> that I do not like<br><strong>għax</strong> because<br><strong>għad hemm</strong> there is still<br><strong>ħafna x’niskopri</strong> much to discover.</td></tr><tr><td>7d. Is-sena l-oħra qattajt ġimgħa Firenze ma’ sħabi, żorna mużewijiet u mxejna ħafna kuljum.</td><td>Last year I spent a week in Florence with my friends, we visited museums and walked a lot every day.<br><strong>Is-sena l-oħra</strong> last year<br><strong>qattajt ġimgħa</strong> I spent a week<br><strong>Firenze ma’ sħabi</strong> in Florence with my friends<br><strong>żorna mużewijiet</strong> we visited museums<br><strong>u mxejna ħafna kuljum</strong> and we walked a lot every day.</td></tr></tbody></table><hr><h2 id="_2-the-hundred-word-writing-task" tabindex="-1">2 The Hundred-Word Writing Task <a class="header-anchor" href="#_2-the-hundred-word-writing-task" aria-label="Permalink to &quot;2 The Hundred-Word Writing Task&quot;">​</a></h2><p><code>Il-Kitba: Agħżel waħda mill-ewwel paġna u ikteb madwar 100 kelma dwarha</code>: writing — choose one of the topics on the first page and write about 100 words. <strong>Agħżel</strong> choose<br><strong>waħda</strong> one<br><strong>mill-ewwel paġna</strong> from the first page, i.e. page 1<br><strong>u ikteb</strong> and write<br><strong>madwar</strong> about, roughly<br><strong>100 kelma</strong> one hundred words<br><strong>dwarha</strong> about it.</p><h3 id="model-essay-jien" tabindex="-1">Model essay: Jien <a class="header-anchor" href="#model-essay-jien" aria-label="Permalink to &quot;Model essay: Jien&quot;">​</a></h3><p>Jisimni Alex u noqgħod l-Imsida ma’ ħabib tiegħi. Għandi tletin sena u naħdem f’uffiċċju żgħir fil-Belt. Ix-xogħol tiegħi jibda fit-tmienja, għalhekk inqum kmieni u nieħu l-karozza tal-linja. Wara x-xogħol nattendi kors tal-Malti darbtejn fil-ġimgħa għax nixtieq nitkellem aħjar mal-ġirien. Fil-ħin liberu nħobb naqra, insajjar u nimxi ħdejn il-baħar. Dawn l-attivitajiet jgħinuni nistrieħ wara ġurnata twila u mimlija xogħol. Is-Sibt normalment niltaqa’ ma’ sħabi u kultant immorru naraw film. Il-familja tiegħi tgħix barra minn Malta, iżda nitkellmu fuq it-telefon kull filgħaxija. Fil-futur nixtieq nkompli nistudja u nsib aktar ħin għall-isport. Jiena persuna kalma u nħobb nitgħallem affarijiet ġodda ma’ nies differenti.</p><p>The text above counts as <strong>100 words</strong> when split on spaces; hyphenated words with the article and words with an apostrophe each count as one written word.</p><h3 id="line-by-line-breakdown" tabindex="-1">Line-by-line breakdown <a class="header-anchor" href="#line-by-line-breakdown" aria-label="Permalink to &quot;Line-by-line breakdown&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sentence</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>Jisimni Alex u noqgħod l-Imsida ma’ ħabib tiegħi.</td><td>My name is Alex and I live in Msida with my friend.<br><strong>Jisimni Alex</strong> I am called Alex<br><strong>u noqgħod</strong> and I live<br><strong>l-Imsida</strong> the place name Msida<br><strong>ma’ ħabib tiegħi</strong> with my friend.</td></tr><tr><td>Għandi tletin sena u naħdem f’uffiċċju żgħir fil-Belt.</td><td>I am thirty years old and work in a small office in Valletta.<br><strong>Għandi</strong> I have<br><strong>tletin sena</strong> thirty years, used for age<br><strong>u naħdem</strong> and I work<br><strong>f’uffiċċju żgħir</strong> in a small office<br><strong>fil-Belt</strong> in Valletta.</td></tr><tr><td>Ix-xogħol tiegħi jibda fit-tmienja, għalhekk inqum kmieni u nieħu l-karozza tal-linja.</td><td>My work starts at eight, so I get up early and take the bus.<br><strong>Ix-xogħol tiegħi</strong> my work<br><strong>jibda</strong> starts<br><strong>fit-tmienja</strong> at eight<br><strong>għalhekk</strong> therefore<br><strong>inqum kmieni</strong> I get up early<br><strong>u nieħu</strong> and I take<br><strong>l-karozza tal-linja</strong> the bus.</td></tr><tr><td>Wara x-xogħol nattendi kors tal-Malti darbtejn fil-ġimgħa għax nixtieq nitkellem aħjar mal-ġirien.</td><td>After work I attend a Maltese course twice a week because I want to speak better with the neighbours.<br><strong>Wara x-xogħol</strong> after work<br><strong>nattendi kors tal-Malti</strong> I attend a Maltese course<br><strong>darbtejn fil-ġimgħa</strong> twice a week<br><strong>għax nixtieq</strong> because I want<br><strong>nitkellem aħjar</strong> to speak better<br><strong>mal-ġirien</strong> with the neighbours.</td></tr><tr><td>Fil-ħin liberu nħobb naqra, insajjar u nimxi ħdejn il-baħar.</td><td>In my free time I like reading, cooking and walking by the sea.<br><strong>Fil-ħin liberu</strong> in free time<br><strong>nħobb naqra</strong> I like reading<br><strong>insajjar</strong> I cook<br><strong>u nimxi</strong> and I walk<br><strong>ħdejn il-baħar</strong> by the sea.</td></tr><tr><td>Dawn l-attivitajiet jgħinuni nistrieħ wara ġurnata twila u mimlija xogħol.</td><td>These activities help me rest after a long, work-filled day.<br><strong>Dawn l-attivitajiet</strong> these activities<br><strong>jgħinuni</strong> they help me, -ni = me<br><strong>nistrieħ</strong> I rest<br><strong>wara ġurnata twila</strong> after a long day<br><strong>u mimlija xogħol</strong> and full of work, mimlija agrees with the feminine ġurnata.</td></tr><tr><td>Is-Sibt normalment niltaqa’ ma’ sħabi u kultant immorru naraw film.</td><td>On Saturday I usually meet my friends and sometimes we go to see a film.<br><strong>Is-Sibt</strong> Saturday<br><strong>normalment</strong> usually<br><strong>niltaqa’ ma’ sħabi</strong> I meet my friends<br><strong>u kultant</strong> and sometimes<br><strong>immorru naraw film</strong> we go to see a film.</td></tr><tr><td>Il-familja tiegħi tgħix barra minn Malta, iżda nitkellmu fuq it-telefon kull filgħaxija.</td><td>My family lives outside Malta, but we talk on the phone every evening.<br><strong>Il-familja tiegħi</strong> my family<br><strong>tgħix</strong> lives, with a singular collective noun<br><strong>barra minn Malta</strong> outside Malta<br><strong>iżda nitkellmu</strong> but we talk<br><strong>fuq it-telefon</strong> on the phone<br><strong>kull filgħaxija</strong> every evening.</td></tr><tr><td>Fil-futur nixtieq nkompli nistudja u nsib aktar ħin għall-isport.</td><td>In the future I want to keep studying and find more time for sport.<br><strong>Fil-futur</strong> in the future<br><strong>nixtieq nkompli</strong> I want to continue<br><strong>nistudja</strong> studying<br><strong>u nsib</strong> and find<br><strong>aktar ħin</strong> more time<br><strong>għall-isport</strong> for sport.</td></tr><tr><td>Jiena persuna kalma u nħobb nitgħallem affarijiet ġodda ma’ nies differenti.</td><td>I am a calm person and I like learning new things with different people.<br><strong>Jiena</strong> I<br><strong>persuna kalma</strong> a calm person; kalma agrees with the feminine noun persuna, not with the speaker&#39;s sex<br><strong>u nħobb nitgħallem</strong> and I like learning<br><strong>affarijiet ġodda</strong> new things<br><strong>ma’ nies differenti</strong> with different people.</td></tr></tbody></table><hr><h2 id="_3-negation-the-rule-and-every-example" tabindex="-1">3 Negation: the Rule and Every Example <a class="header-anchor" href="#_3-negation-the-rule-and-every-example" aria-label="Permalink to &quot;3 Negation: the Rule and Every Example&quot;">​</a></h2><h3 id="the-negative-pattern-and-the-rules-given-in-the-textbook" tabindex="-1">The negative pattern and the rules given in the textbook <a class="header-anchor" href="#the-negative-pattern-and-the-rules-given-in-the-textbook" aria-label="Permalink to &quot;The negative pattern and the rules given in the textbook&quot;">​</a></h3><p><code>Il-Grammatika: In-Negattiv</code> = grammar: the negative. The core frame is <strong>ma + verb + x</strong>; <strong>m’</strong> is the contracted form of ma, and <strong>x</strong> attaches to the verb or to the verb-plus-suffix group.</p><table tabindex="0"><thead><tr><th>Original</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>Ma nafx.</td><td>I do not know.<br><strong>Ma … x</strong> the negative frame<br><strong>naf</strong> I know<br><strong>nafx</strong> naf plus x, not an English-style separate &quot;not&quot;.</td></tr><tr><td>Ma rridx.</td><td>I do not want.<br><strong>Ma … x</strong> negation<br><strong>rrid</strong> I want, the positive form is often irrid<br><strong>rridx</strong> the form inside the negative.</td></tr><tr><td>M’għamilx.</td><td>He did not do it.<br><strong>M’</strong> ma contracted<br><strong>għamilx</strong> the negative form of għamel, note the vowel.</td></tr><tr><td>M’għedtlix.</td><td>You did not tell me.<br><strong>M’</strong> ma contracted<br><strong>għedt</strong> the past &quot;I / you said&quot; share one form; here the second person is taken from the textbook and the &quot;to me&quot; context<br><strong>-li</strong> to me<br><strong>-x</strong> the negative, placed after the pronoun suffix.</td></tr><tr><td>Il-verbi, li huma kliem li juru azzjoni jew stat, jistgħu juru n-negattiv, juri li l-azzjoni ma seħħitx.</td><td>The textbook sentence is loose in syntax; it means verbs name an action or a state and can also form the negative, showing that the action did not happen.<br><strong>Il-verbi</strong> the verbs<br><strong>li huma kliem</strong> which are words<br><strong>li juru</strong> that show<br><strong>azzjoni jew stat</strong> action or state<br><strong>jistgħu juru n-negattiv</strong> they can show the negative<br><strong>juri li</strong> shows that<br><strong>l-azzjoni ma seħħitx</strong> the action did not take place.</td></tr><tr><td>Normalment, in-negattiv isir billi quddiem il-verb tiżdied il-‘ma’ u wara l-verb tingħaqad ix-x. Eżempju:</td><td>Normally the negative is made by adding ma before the verb and joining x after the verb. Example:<br><strong>Normalment</strong> normally<br><strong>in-negattiv isir</strong> the negative is made<br><strong>billi</strong> by<br><strong>quddiem il-verb</strong> before the verb<br><strong>tiżdied il-ma</strong> ma is added<br><strong>u wara l-verb</strong> and after the verb<br><strong>tingħaqad ix-x</strong> x is joined<br><strong>Eżempju</strong> example.</td></tr><tr><td>Meta l-verb jispiċċa bil-vokali ‘a’ fin-negattiv din tinbidel f’ ‘ie’.</td><td>The textbook says a verb ending in a changes to ie in the negative; this is a simplified local rule and must be checked against the examples.<br><strong>Meta</strong> when<br><strong>l-verb jispiċċa</strong> the verb ends<br><strong>bil-vokali a</strong> in the vowel a<br><strong>fin-negattiv</strong> in the negative<br><strong>din tinbidel f’ ie</strong> it changes to ie.</td></tr><tr><td>Il-verb li jispiċċa bl-appostrofi f’tarf il-kelma, sinjal li l-kelma għandha l-għajn, fin-negattiv l-appostrofu jaqa’.</td><td>A final apostrophe is linked to the historical għ; in the negative the apostrophe is dropped. This is about the spelling of these verbs, not about deleting every apostrophe inside a word.<br><strong>li jispiċċa bl-appostrofi</strong> that ends with an apostrophe<br><strong>f’tarf il-kelma</strong> at the end of the word<br><strong>sinjal</strong> a sign<br><strong>li l-kelma għandha l-għajn</strong> that the word has għ<br><strong>fin-negattiv</strong> in the negative<br><strong>l-appostrofu jaqa’</strong> the apostrophe drops.</td></tr></tbody></table><h3 id="positive-to-negative-all-sentences-completed" tabindex="-1">Positive to negative, all sentences completed <a class="header-anchor" href="#positive-to-negative-all-sentences-completed" aria-label="Permalink to &quot;Positive to negative, all sentences completed&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Positive → negative</th><th>Chinese and words</th></tr></thead><tbody><tr><td>It-tifel kiel. → It-tifel <strong>ma kielx</strong>.</td><td>The boy ate → the boy did not eat.<br><strong>It-tifel</strong> the boy<br><strong>kiel</strong> he ate<br><strong>ma kielx</strong> he did not eat.</td></tr><tr><td>Marru lura d-dar. → <strong>Ma marrux</strong> lura d-dar.</td><td>They went back home → they did not go back home.<br><strong>marru</strong> they went<br><strong>lura d-dar</strong> back home<br><strong>ma marrux</strong> they did not go.</td></tr><tr><td>Ra kollox mill-bogħod. → <strong>Ma rax</strong> kollox mill-bogħod.</td><td>He saw everything from far away → he did not see everything from far away.<br><strong>ra / ma rax</strong> saw / did not see<br><strong>kollox</strong> everything; &quot;did not see everything&quot; does not mean &quot;saw nothing&quot;<br><strong>mill-bogħod</strong> from far away.</td></tr><tr><td>Sergio tefa d-dawl. → Sergio <strong>ma tefiex</strong> id-dawl.</td><td>Sergio turned off the light → he did not turn off the light.<br><strong>tefa</strong> to put out, switch off, no final apostrophe<br><strong>ma tefiex</strong> did not switch off, a → ie<br><strong>d-dawl / id-dawl</strong> the light, the article takes different forms by sound environment.</td></tr><tr><td>L-għalliema tawna x-xogħol għad-dar. → L-għalliema <strong>ma tawniex</strong> ix-xogħol għad-dar.</td><td>The teachers gave us homework → they did not give us homework.<br><strong>L-għalliema</strong> here plural teachers, shown by tawna<br><strong>tawna</strong> they gave us, taw + na<br><strong>ma tawniex</strong> did not give us, -na becomes -nie before x<br><strong>ix-xogħol għad-dar</strong> homework.</td></tr><tr><td>Waqa’ fuq il-bankina. → <strong>Ma waqax</strong> fuq il-bankina.</td><td>He fell on the pavement → he did not fall.<br><strong>waqa’</strong> he fell<br><strong>ma waqax</strong> did not fall, apostrophe dropped before x<br><strong>fuq il-bankina</strong> on the pavement.</td></tr><tr><td>Tefa’ l-ġebel fil-knisja. → <strong>Ma tefax</strong> il-ġebel fil-knisja.</td><td>He threw the stone into the church → he did not throw it.<br><strong>tefa’</strong> to throw, with an apostrophe, unlike tefa = switch off<br><strong>ma tefax</strong> did not throw<br><strong>il-ġebel</strong> the stone<br><strong>fil-knisja</strong> into / in the church.</td></tr></tbody></table><hr><h2 id="_4-negative-practice-a-and-b" tabindex="-1">4 Negative Practice A and B <a class="header-anchor" href="#_4-negative-practice-a-and-b" aria-label="Permalink to &quot;4 Negative Practice A and B&quot;">​</a></h2><h3 id="practice-a-five-sentences" tabindex="-1">Practice A: five sentences <a class="header-anchor" href="#practice-a-five-sentences" aria-label="Permalink to &quot;Practice A: five sentences&quot;">​</a></h3><p><code>Taħriġ marbut man-negattiv</code> = an exercise connected with the negative. <strong>Taħriġ</strong> exercise<br><strong>marbut ma’</strong> connected with. <code>Aqleb dawn is-sentenzi fin-negattiv</code> = turn these sentences into the negative; <strong>Aqleb</strong> turn<br><strong>dawn is-sentenzi</strong> these sentences<br><strong>fin-negattiv</strong> into the negative.</p><p>The rewrites below negate every main predicate as the exercise asks; they do not mean the original story really turned into the opposite event.</p><table tabindex="0"><thead><tr><th>Original → model negative</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Ilbieraħ it-tifel qam marid. Ħa riħ qawwi. → Ilbieraħ it-tifel <strong>ma qamx</strong> marid. <strong>Ma ħax</strong> riħ qawwi.</td><td>Yesterday the boy got up ill and caught a bad cold → he did not get up ill and did not catch a bad cold.<br><strong>Ilbieraħ</strong> yesterday<br><strong>it-tifel</strong> the boy<br><strong>qam / ma qamx</strong> got up / did not get up, read together with marid<br><strong>marid</strong> ill<br><strong>ħa / ma ħax</strong> caught / did not catch<br><strong>riħ qawwi</strong> a bad cold; riħ can also mean wind, here a fixed phrase.</td></tr><tr><td>2. Jaqa’ kuljum. Għandu bżonn bastun. → <strong>Ma jaqax</strong> kuljum. <strong>M’għandux</strong> bżonn bastun.</td><td>He falls every day and needs a stick → he does not fall every day and does not need a stick.<br><strong>jaqa’ / ma jaqax</strong> falls / does not fall<br><strong>kuljum</strong> every day; &quot;not every day&quot; is not &quot;never&quot;<br><strong>għandu bżonn / m’għandux bżonn</strong> needs / does not need<br><strong>bastun</strong> a walking stick.</td></tr><tr><td>3. Erfajtu u meddejtu fuq is-sodda. → <strong>Ma erfajtux</strong> u <strong>ma meddejtux</strong> fuq is-sodda.</td><td>I lifted him and laid him on the bed → I did not lift him and did not lay him on the bed.<br><strong>erfajtu</strong> I / you lifted him, -u = him<br><strong>ma erfajtux</strong> did not lift him, x after -u<br><strong>u</strong> and<br><strong>meddejtu / ma meddejtux</strong> laid him flat / did not lay him flat<br><strong>fuq is-sodda</strong> on the bed<br><strong>-t</strong> here the past &quot;I / you&quot; share one form; the translation takes &quot;I&quot;.</td></tr><tr><td>4. Beka ħafna lil ommu. → <strong>Ma bekiex</strong> ħafna lil ommu.</td><td>He cried a lot for his mother → he did not cry a lot for his mother.<br><strong>beka / ma bekiex</strong> cried / did not cry, a → ie<br><strong>ħafna</strong> a lot<br><strong>lil ommu</strong> for / towards his mother, the exact relation depends on context.</td></tr><tr><td>5. Mexa lura d-dar u sar għasra bix-xita. → <strong>Ma mexiex</strong> lura d-dar u <strong>ma sarx</strong> għasra bix-xita.</td><td>He walked back home and got soaked in the rain → he did not walk back home and did not get soaked.<br><strong>mexa / ma mexiex</strong> walked / did not walk<br><strong>lura d-dar</strong> back home<br><strong>u</strong> and<br><strong>sar / ma sarx</strong> became / did not become<br><strong>għasra</strong> soaked through<br><strong>bix-xita</strong> with the rain.</td></tr></tbody></table><h3 id="practice-b-ten-items" tabindex="-1">Practice B: ten items <a class="header-anchor" href="#practice-b-ten-items" aria-label="Permalink to &quot;Practice B: ten items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Given predicate and full answer</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. kilt → Jien <strong>ma kiltx</strong> ir-ross.</td><td>I did not eat the rice.<br><strong>Jien</strong> I<br><strong>kilt / ma kiltx</strong> I ate / I did not eat<br><strong>ir-ross</strong> the rice.</td></tr><tr><td>2. raqdet → Tina <strong>ma raqditx</strong> sewwa.</td><td>Tina did not sleep well.<br><strong>Tina</strong> a female name<br><strong>raqdet / ma raqditx</strong> she slept / she did not sleep, note e → i<br><strong>sewwa</strong> well, properly.</td></tr><tr><td>3. ħadem → Gino <strong>ma ħadimx</strong> sa tard billejl.</td><td>Gino did not work until late at night.<br><strong>Gino</strong> a name<br><strong>ħadem / ma ħadimx</strong> he worked / he did not work<br><strong>sa tard</strong> until late<br><strong>billejl</strong> at night.</td></tr><tr><td>4. studjaw → It-tfal <strong>ma studjawx</strong> għall-eżami.</td><td>The children did not study for the exam.<br><strong>It-tfal</strong> the children<br><strong>studjaw / ma studjawx</strong> they studied / did not study<br><strong>għall-eżami</strong> for the exam.</td></tr><tr><td>5. waslet → L-għalliema <strong>ma waslitx</strong> kmieni.</td><td>The (female) teacher did not arrive early.<br><strong>L-għalliema</strong> here one female teacher, shown by waslet<br><strong>waslet / ma waslitx</strong> she arrived / she did not arrive<br><strong>kmieni</strong> early.</td></tr><tr><td>6. saqsa → Il-wejter <strong>ma saqsiex</strong> bl-edukazzjoni.</td><td>The waiter did not ask politely.<br><strong>Il-wejter</strong> the waiter<br><strong>saqsa / ma saqsiex</strong> asked / did not ask<br><strong>bl-edukazzjoni</strong> politely, not &quot;with education&quot;.</td></tr><tr><td>7. xtrat → Ommi <strong>ma xtratx</strong> il-laħam.</td><td>My mother did not buy the meat.<br><strong>Ommi</strong> my mother<br><strong>xtrat / ma xtratx</strong> she bought / she did not buy<br><strong>il-laħam</strong> the meat.</td></tr><tr><td>8. nieħu → Jien <strong>ma niħux</strong> ġelat kuljum.</td><td>I do not have ice cream every day.<br><strong>Jien</strong> I<br><strong>nieħu / ma niħux</strong> I take / eat, I do not take / eat, note the stem change<br><strong>ġelat</strong> ice cream<br><strong>kuljum</strong> every day.</td></tr><tr><td>9. Original Hija jimxi, first corrected to timxi → Hija <strong>ma timxix</strong> ħames kilometri kull filgħodu.</td><td>She does not walk five kilometres every morning.<br><strong>Hija</strong> she<br><strong>jimxi</strong> he walks, not agreeing with Hija<br><strong>timxi / ma timxix</strong> she walks / she does not walk<br><strong>ħames kilometri</strong> five kilometres, expanding 5km<br><strong>kull filgħodu</strong> every morning.</td></tr><tr><td>10. jsuq → Missieri <strong>ma jsuqx</strong> il-vannijiet tal-iskola.</td><td>My father does not drive the school vans.<br><strong>Missieri</strong> my father<br><strong>jsuq / ma jsuqx</strong> he drives / he does not drive<br><strong>il-vannijiet</strong> the vans<br><strong>tal-iskola</strong> of the school.</td></tr></tbody></table><hr><h2 id="_5-the-definite-article-everything-filled-in" tabindex="-1">5 The Definite Article: Everything Filled In <a class="header-anchor" href="#_5-the-definite-article-everything-filled-in" aria-label="Permalink to &quot;5 The Definite Article: Everything Filled In&quot;">​</a></h2><p><code>L-Artiklu – Imla l-vojt bl-artiklu li jixraq</code> = the article — fill the blank with the suitable article. <strong>l-artiklu</strong> the article<br><strong>Imla l-vojt</strong> fill the blank<br><strong>bl-artiklu</strong> with the article<br><strong>li jixraq</strong> that fits. <code>Ikteb l-artiklu quddiem in-nomi</code> = write the article before the nouns; <strong>quddiem</strong> before<br><strong>in-nomi</strong> the nouns.</p><p>The basic form is <strong>il-</strong>; before a vowel it is often <strong>l-</strong>; before some consonants it is assimilated, e.g. <strong>it-tadam, iż-żebbuġ, is-salamun</strong>. When the preceding word ends in a vowel the initial i can be dropped, e.g. <strong>nitfa’ t-tadam</strong>. Prepositions contract with the article: <strong>minn + il- → mill-</strong>, <strong>bi + il- → bil- / bl-</strong>. Do not confuse ħ and ġ with other letters.</p><h3 id="group-a-full-sentences" tabindex="-1">Group A, full sentences <a class="header-anchor" href="#group-a-full-sentences" aria-label="Permalink to &quot;Group A, full sentences&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Full sentence, group A</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Fl-insalata nitfa’ <strong>t-tadam, il-ħass, il-ħjar, it-tonn taż-żejt, iż-żebbuġ, il-kappar, il-fażola bajda, il-ġbejna tal-bżar</strong> u bajda mgħollija.</td><td>In the salad I put tomato, lettuce, cucumber, tuna in oil, olives, capers, white beans, pepper cheeselet and a boiled egg.<br><strong>Fl-insalata</strong> in the salad<br><strong>nitfa’</strong> I put<br><strong>t-tadam</strong> tomato, t- after a preceding final vowel<br><strong>il-ħass</strong> lettuce<br><strong>il-ħjar</strong> cucumber<br><strong>it-tonn taż-żejt</strong> tuna in oil<br><strong>iż-żebbuġ</strong> olives<br><strong>il-kappar</strong> capers<br><strong>il-fażola bajda</strong> white beans<br><strong>il-ġbejna tal-bżar</strong> the small peppered cheeselet<br><strong>u bajda mgħollija</strong> and a boiled egg; not every bajda is &quot;white&quot;.</td></tr><tr><td>2. Għall-iskola għandi bżonn <strong>il-kotba</strong> tal-Malti u <strong>l-Ingliż, il-pokit</strong> u <strong>l-karti</strong>.</td><td>For school I need the Maltese books and English, the pencil case and the papers.<br><strong>Għall-iskola</strong> for school<br><strong>għandi bżonn</strong> I need<br><strong>il-kotba</strong> the books<br><strong>tal-Malti</strong> of Maltese<br><strong>u l-Ingliż</strong> and English, only the article is filled in as the exercise asks<br><strong>il-pokit</strong> the pencil case<br><strong>u l-karti</strong> and the papers<br><strong>Natural phrasing</strong> if both school subjects are meant, write il-kotba tal-Malti u tal-Ingliż; the second tal- is an extra revision, not a one-word article fill.</td></tr><tr><td>3. <strong>It-Taljan</strong> u <strong>l-Ispanjol</strong> <strong>huma ż-żewġ</strong> lingwi favoriti tiegħi.</td><td>Italian and Spanish are my two favourite languages.<br><strong>It-Taljan</strong> Italian<br><strong>u l-Ispanjol</strong> and Spanish<br><strong>huma</strong> they are; the original huwa is singular and is corrected here<br><strong>ż-żewġ lingwi</strong> the two languages<br><strong>favoriti tiegħi</strong> my favourite, plural.</td></tr><tr><td>4. Itħan <strong>iċ-ċiċri</strong> friska, <strong>l-ispinaċi</strong> u <strong>l-ful</strong>.</td><td>Grind the fresh chickpeas, the spinach and the broad beans.<br><strong>Itħan</strong> grind, imperative<br><strong>iċ-ċiċri</strong> chickpeas, assimilated before ċ<br><strong>friska</strong> fresh, keeping the textbook&#39;s collective-noun agreement<br><strong>l-ispinaċi</strong> spinach, l- before a vowel<br><strong>u l-ful</strong> and broad beans, the i may drop after a preceding vowel-final u.</td></tr><tr><td>5. <strong>Is-salamun</strong> inħobb nimmarinah bil-lumi, <strong>l-għasel</strong> u <strong>t-tewm</strong>.</td><td>I like to marinate the salmon with lemon, honey and garlic.<br><strong>Is-salamun</strong> the salmon<br><strong>inħobb</strong> I like<br><strong>nimmarinah</strong> I marinate it, -h refers back to the fish<br><strong>bil-lumi</strong> with the lemon<br><strong>l-għasel</strong> the honey<br><strong>u t-tewm</strong> and the garlic<br><strong>Note</strong> here the articles are filled in as the exercise lists the items; if each marinade is stressed one could write bil-lumi, bl-għasel u bit-tewm.</td></tr></tbody></table><h3 id="group-b-full-sentences" tabindex="-1">Group B, full sentences <a class="header-anchor" href="#group-b-full-sentences" aria-label="Permalink to &quot;Group B, full sentences&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Full sentence, group B</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. <strong>It-tifel</strong> kiel tard ħafna u raqad fuq <strong>is-sodda</strong>.</td><td>The boy ate very late and slept on the bed.<br><strong>It-tifel</strong> the boy, t assimilated<br><strong>kiel tard ħafna</strong> ate very late<br><strong>u raqad</strong> and slept<br><strong>fuq is-sodda</strong> on the bed, s assimilated.</td></tr><tr><td>2. Morna nixtru <strong>l-ikel</strong> għal filgħaxija.</td><td>We went to buy the food for the evening.<br><strong>Morna</strong> we went<br><strong>nixtru</strong> to buy<br><strong>l-ikel</strong> the food, l- before a vowel<br><strong>għal filgħaxija</strong> for the evening.</td></tr><tr><td>3. Martha u Grace għalqu <strong>t-tieqa</strong> tad-dar tagħhom.</td><td>Martha and Grace closed the window of their house.<br><strong>Martha u Grace</strong> two names<br><strong>għalqu</strong> they closed, t- after final u<br><strong>t-tieqa</strong> the window<br><strong>tad-dar tagħhom</strong> of their house.</td></tr><tr><td>4. <strong>Il-missier</strong> tat-tifel talbu jġiblu <strong>l-ilma</strong> u <strong>l-ħobż mill-bank</strong> tal-kċina.</td><td>The boy&#39;s father asked him to bring him the water and the bread from the kitchen counter.<br><strong>Il-missier</strong> the father<br><strong>tat-tifel</strong> of the boy<br><strong>talbu</strong> he asked him, talab + u; a final u alone does not make it &quot;they asked&quot;<br><strong>jġiblu</strong> bring him<br><strong>l-ilma u l-ħobż</strong> the water and the bread<br><strong>mill-bank</strong> from the counter, minn + il-bank must contract<br><strong>tal-kċina</strong> of the kitchen.</td></tr><tr><td>5. <strong>Il-mara</strong> u <strong>r-raġel</strong> marru jixtru <strong>l-Belt</strong> u xtraw <strong>iż-żarbun</strong> u <strong>s-siġra</strong> tal-Milied li għandhom ġewwa <strong>s-salott</strong>.</td><td>The woman and the man went shopping in Valletta and bought shoes and the Christmas tree they have in the living room.<br><strong>Il-mara u r-raġel</strong> the woman and the man<br><strong>marru jixtru</strong> they went to buy<br><strong>l-Belt</strong> to Valletta; here it is not &quot;buying the city&quot;<br><strong>u xtraw</strong> and they bought<br><strong>iż-żarbun</strong> shoes, a collective<br><strong>u s-siġra tal-Milied</strong> and the Christmas tree<br><strong>li għandhom</strong> that they have<br><strong>ġewwa s-salott</strong> in the living room.</td></tr></tbody></table><hr><h2 id="_6-pronouns-reading-grouping-and-sentences" tabindex="-1">6 Pronouns: Reading, Grouping and Sentences <a class="header-anchor" href="#_6-pronouns-reading-grouping-and-sentences" aria-label="Permalink to &quot;6 Pronouns: Reading, Grouping and Sentences&quot;">​</a></h2><h3 id="the-reading-passage-line-by-line" tabindex="-1">The reading passage, line by line <a class="header-anchor" href="#the-reading-passage-line-by-line" aria-label="Permalink to &quot;The reading passage, line by line&quot;">​</a></h3><p><code>Il-Pronomi Personali, Demostrattivi u Interrogattivi – Sibhom mis-silta u mmarkahom b’kuluri differenti</code> = find the personal, demonstrative and interrogative pronouns in the passage and mark them in different colours.</p><p><strong>Il-pronomi</strong> pronouns<br><strong>personali</strong> personal<br><strong>demostrattivi</strong> demonstrative, as in the textbook title<br><strong>interrogattivi</strong> interrogative<br><strong>Sibhom</strong> find them<br><strong>mis-silta</strong> from the passage<br><strong>u mmarkahom</strong> and mark them<br><strong>b’kuluri differenti</strong> in different colours. Text labels are used below so that colour coding does not fail in different readers.</p><table tabindex="0"><thead><tr><th>Original sentence</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>“Liema waħda trid?”, saqsietni Rita tal-laħam.</td><td>&quot;Which one do you want?&quot; Rita of the butcher&#39;s asked me.<br><strong>Liema</strong> which one, interrogative determiner / pronoun<br><strong>waħda</strong> one piece / one, feminine<br><strong>trid</strong> you want<br><strong>saqsietni</strong> she asked me, -ni = me<br><strong>Rita tal-laħam</strong> Rita of the meat shop.</td></tr><tr><td>Jien weġibtha “dik tan-naħa tal-lemin, għax ikbar!”.</td><td>I answered her: &quot;that one on the right, because it is bigger!&quot;<br><strong>Jien</strong> I<br><strong>weġibtha</strong> I answered her, -ha = her<br><strong>dik</strong> that one, feminine<br><strong>tan-naħa tal-lemin</strong> of the right side<br><strong>għax</strong> because<br><strong>ikbar</strong> bigger.</td></tr><tr><td>Hi b’daħka daqsiex weġbitni “Din trid, u din nagħtik!”.</td><td>Smiling broadly she answered me: &quot;This one you want, and this one I give you!&quot;<br><strong>Hi</strong> she, the short form of hija<br><strong>b’daħka daqsiex</strong> with a big smile<br><strong>weġbitni</strong> she answered me<br><strong>Din trid</strong> this one you want<br><strong>u din nagħtik</strong> and this one I give you, -k = to you.</td></tr><tr><td>Biċċa laħam friska u tajba għall-ikla ta’ filgħaxija.</td><td>A piece of fresh, good meat for the evening meal. In the original it is a noun phrase with no full predicate.<br><strong>Biċċa laħam</strong> a piece of meat<br><strong>friska u tajba</strong> fresh and good, feminine agreeing with biċċa<br><strong>għall-ikla</strong> for the meal<br><strong>ta’ filgħaxija</strong> of the evening.</td></tr><tr><td>Din kienet l-ikla favorita tiegħi u kont nieħu gost insajjarha wkoll.</td><td>This was my favourite meal and I also enjoyed cooking it.<br><strong>Din</strong> this, feminine<br><strong>kienet</strong> it was<br><strong>l-ikla favorita tiegħi</strong> my favourite meal<br><strong>u kont nieħu gost</strong> and I used to enjoy<br><strong>insajjarha</strong> I cook it, -ha refers to ikla<br><strong>wkoll</strong> also.</td></tr><tr><td>Mal-laħam inżid il-bżar tal-kulur, il-basal u l-patata u nsajjar kollox fil-forn.</td><td>With the meat I add peppers, onion and potatoes and cook everything in the oven.<br><strong>Mal-laħam</strong> with the meat<br><strong>inżid</strong> I add<br><strong>il-bżar tal-kulur</strong> bell peppers<br><strong>il-basal</strong> onion<br><strong>u l-patata</strong> and potatoes<br><strong>u nsajjar</strong> and cook<br><strong>kollox</strong> everything<br><strong>fil-forn</strong> in the oven.</td></tr><tr><td>“Xi ħaġa oħra?”, reġgħet Rita.</td><td>&quot;Anything else?&quot; Rita said again.<br><strong>Xi ħaġa oħra</strong> anything else; here xi modifies ħaġa and is not a standalone question word<br><strong>reġgħet</strong> she again, with &quot;said / asked&quot; omitted<br><strong>Rita</strong> the name.</td></tr><tr><td>“Le dak kollox”, weġibtha jien.</td><td>&quot;No, that is all,&quot; I answered her.<br><strong>Le</strong> no<br><strong>dak kollox</strong> that is all<br><strong>weġibtha</strong> I answered her<br><strong>jien</strong> I, added for emphasis.</td></tr></tbody></table><h3 id="the-grouping-answer" tabindex="-1">The grouping answer <a class="header-anchor" href="#the-grouping-answer" aria-label="Permalink to &quot;The grouping answer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Items in the passage and notes</th></tr></thead><tbody><tr><td>Independent personal pronouns</td><td><strong>Jien / jien</strong> I, twice.<br><strong>Hi</strong> she.</td></tr><tr><td>Attached personal / object elements</td><td><strong>-ni</strong> &quot;me&quot; in saqsietni and weġbitni.<br><strong>-ha</strong> &quot;her&quot; in weġibtha, &quot;it&quot; in insajjarha.<br><strong>-k</strong> &quot;to you&quot; in nagħtik.<br>The n-, t- person markers on verbs should not be coloured as independent personal pronouns.</td></tr><tr><td>Demonstratives</td><td><strong>dik</strong> that one.<br><strong>Din / din</strong> this one / this (meal), several times.<br><strong>dak</strong> that / all of that.</td></tr><tr><td>Interrogatives</td><td><strong>Liema</strong> which one.<br><strong>Xi</strong> the interrogative element in Xi ħaġa oħra; strictly it is not a standalone pronoun here.</td></tr><tr><td>Possessive / other</td><td><strong>tiegħi</strong> my, a possessive form.<br><strong>kollox</strong> everything, an indefinite pronoun.<br><strong>waħda</strong> one / a piece, able to stand for the previously unnamed piece of meat.</td></tr></tbody></table><h3 id="five-fuller-sentences" tabindex="-1">Five fuller sentences <a class="header-anchor" href="#five-fuller-sentences" aria-label="Permalink to &quot;Five fuller sentences&quot;">​</a></h3><p><code>Agħżel ħames partiċelli u ikteb sentenza b’kull waħda</code> = choose five items and write one sentence with each. <strong>agħżel</strong> choose<br><strong>ħames</strong> five<br><strong>partiċelli</strong> particles, the textbook&#39;s broad word for small elements<br><strong>b’kull waħda</strong> with each one. The pronouns of this page are used here, so the loose task is not turned into one fixed word list.</p><table tabindex="0"><thead><tr><th>Example sentence</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td><strong>Jien</strong> immur għall-kors tal-Malti wara x-xogħol għax nixtieq nitkellem aħjar mal-ġirien.</td><td>I go to the Maltese course after work because I want to speak better with the neighbours.<br><strong>Jien</strong> I<br><strong>immur għall-kors tal-Malti</strong> I go to the Maltese course<br><strong>wara x-xogħol</strong> after work<br><strong>għax nixtieq</strong> because I want<br><strong>nitkellem aħjar</strong> to speak better<br><strong>mal-ġirien</strong> with the neighbours.</td></tr><tr><td><strong>Hi</strong> tħobb issajjar għall-familja u kull nhar ta’ Ħadd tipprova riċetta ġdida.</td><td>She likes cooking for the family and tries a new recipe every Sunday.<br><strong>Hi</strong> she<br><strong>tħobb issajjar</strong> likes cooking<br><strong>għall-familja</strong> for the family<br><strong>u kull nhar ta’ Ħadd</strong> and every Sunday<br><strong>tipprova</strong> she tries<br><strong>riċetta ġdida</strong> a new recipe.</td></tr><tr><td><strong>Din</strong> hija l-bagalja tiegħi, u fiha poġġejt il-ħwejjeġ kollha għall-vaganza ta’ ġimgħa.</td><td>This is my suitcase, and in it I put all the clothes for a one-week holiday.<br><strong>Din</strong> this, feminine<br><strong>hija l-bagalja tiegħi</strong> is my suitcase<br><strong>u fiha</strong> and in it<br><strong>poġġejt</strong> I put<br><strong>il-ħwejjeġ kollha</strong> all the clothes<br><strong>għall-vaganza ta’ ġimgħa</strong> for a one-week holiday.</td></tr><tr><td><strong>Dik</strong> il-lukanda qrib l-istazzjon hija komda u għandha kmamar kbar għall-familji.</td><td>That hotel near the station is comfortable and has large rooms for families.<br><strong>Dik il-lukanda</strong> that hotel<br><strong>qrib l-istazzjon</strong> near the station<br><strong>hija komda</strong> is comfortable<br><strong>u għandha</strong> and it has<br><strong>kmamar kbar</strong> large rooms, plural<br><strong>għall-familji</strong> for families.</td></tr><tr><td><strong>Liema</strong> ferrovija għandna nieħdu biex naslu Firenze qabel il-ħin tal-ikla ta’ nofsinhar?</td><td>Which train should we take to reach Florence before lunchtime?<br><strong>Liema ferrovija</strong> which train<br><strong>għandna nieħdu</strong> we should take<br><strong>biex naslu Firenze</strong> in order to reach Florence<br><strong>qabel</strong> before<br><strong>il-ħin tal-ikla ta’ nofsinhar</strong> lunchtime.</td></tr></tbody></table><hr><h2 id="_7-possessive-pronouns-pictures-matching-and-choices" tabindex="-1">7 Possessive Pronouns: Pictures, Matching and Choices <a class="header-anchor" href="#_7-possessive-pronouns-pictures-matching-and-choices" aria-label="Permalink to &quot;7 Possessive Pronouns: Pictures, Matching and Choices&quot;">​</a></h2><h3 id="the-picture-task-and-the-first-matching-task" tabindex="-1">The picture task and the first matching task <a class="header-anchor" href="#the-picture-task-and-the-first-matching-task" aria-label="Permalink to &quot;The picture task and the first matching task&quot;">​</a></h3><p><code>Il-pronomi possessivi</code> = possessive pronouns. <code>Qabbel l-istampi mas-sentenzi billi tikteb in-numru fuq il-linja</code> = match the pictures with the sentences by writing the number on the line.</p><p><strong>Qabbel</strong> match<br><strong>l-istampi</strong> the pictures<br><strong>mas-sentenzi</strong> with the sentences<br><strong>billi tikteb</strong> by writing<br><strong>in-numru</strong> the number<br><strong>fuq il-linja</strong> on the line.</p><p>The picture task, in blank order: <strong>Tagħhom → 2, Tagħha → 3, Tiegħu → 1</strong>. The first belongs to plural owners, the other two to a female and a male owner.</p><p>The second task, <code>Qabbel il-pronomi possessivi mas-sentenzi tal-ewwel kolonna</code> = match the possessive forms with the sentences in the first column; <strong>tal-ewwel kolonna</strong> of the first column.</p><table tabindex="0"><thead><tr><th>First column → correct match</th><th>Chinese and words</th></tr></thead><tbody><tr><td>1. Jien għandi kelb. → Dak <strong>tiegħi</strong>.</td><td>I have a dog. That one is mine.<br><strong>Jien</strong> I<br><strong>għandi</strong> I have<br><strong>kelb</strong> a dog<br><strong>Dak tiegħi</strong> that one is mine; tiegħi does not change with the speaker&#39;s sex.</td></tr><tr><td>2. Int għandek qattus. → Dak <strong>tiegħek</strong>.</td><td>You have a cat. That one is yours.<br><strong>Int</strong> you<br><strong>għandek</strong> you have<br><strong>qattus</strong> a cat<br><strong>Dak tiegħek</strong> that one is yours.</td></tr><tr><td>3. Hu għandu żiemel. → Dak <strong>tiegħu</strong>.</td><td>He has a horse. That one is his.<br><strong>Hu</strong> he<br><strong>għandu</strong> he has<br><strong>żiemel</strong> a horse<br><strong>Dak tiegħu</strong> that one is his.</td></tr><tr><td>4. Hi għandha ħanżir. → Dak <strong>tagħha</strong>.</td><td>She has a pig. That one is hers.<br><strong>Hi</strong> she<br><strong>għandha</strong> she has<br><strong>ħanżir</strong> a pig<br><strong>Dak tagħha</strong> that one is hers.</td></tr><tr><td>5. Aħna għandna serduk. → Dak <strong>tagħna</strong>.</td><td>We have a rooster. That one is ours.<br><strong>Aħna</strong> we<br><strong>għandna</strong> we have<br><strong>serduk</strong> a rooster<br><strong>Dak tagħna</strong> that one is ours.</td></tr><tr><td>6. Intom għandkom ħmar. → Dak <strong>tagħkom</strong>.</td><td>You (plural) have a donkey. That one is yours.<br><strong>Intom</strong> you plural<br><strong>għandkom</strong> you have<br><strong>ħmar</strong> a donkey<br><strong>Dak tagħkom</strong> that one is yours.</td></tr><tr><td>7. Huma għandhom barri. → Dak <strong>tagħhom</strong>.</td><td>They have a bull. That one is theirs.<br><strong>Huma</strong> they<br><strong>għandhom</strong> they have<br><strong>barri</strong> a bull<br><strong>Dak tagħhom</strong> that one is theirs.</td></tr></tbody></table><h3 id="five-multiple-choice-items" tabindex="-1">Five multiple-choice items <a class="header-anchor" href="#five-multiple-choice-items" aria-label="Permalink to &quot;Five multiple-choice items&quot;">​</a></h3><p><code>Aqta’ linja taħt it-tweġiba t-tajba</code> = underline the correct answer; <strong>Aqta’ linja</strong> here draw a line<br><strong>taħt</strong> under<br><strong>it-tweġiba t-tajba</strong> the correct answer.</p><table tabindex="0"><thead><tr><th>Full answer</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Dak il-kelb tat-tifel. Il-kelb <strong>tiegħu</strong> jismu Jack.</td><td>That dog is the boy&#39;s. His dog is called Jack.<br><strong>Dak il-kelb</strong> that dog<br><strong>tat-tifel</strong> of the boy<br><strong>Il-kelb tiegħu</strong> his dog; look at the sex of the owner, tifel<br><strong>jismu Jack</strong> he is called Jack.</td></tr><tr><td>2. Id-dar ta’ dik il-<strong>koppja</strong> hija kbira. Id-dar <strong>tagħhom</strong> fiha sebat ikmamar.</td><td>That couple&#39;s house is large. Their house has seven rooms.<br><strong>Id-dar</strong> the house<br><strong>ta’ dik il-koppja</strong> of that couple; the original kopja means a copy, corrected here from the context<br><strong>hija kbira</strong> is large<br><strong>tagħhom</strong> theirs, the couple being plural owners<br><strong>fiha</strong> in it<br><strong>sebat ikmamar</strong> seven rooms, the numeral form before a vowel.</td></tr><tr><td>3. Daniel ħabib kbir. <strong>Huwa</strong> l-akbar ħabib <strong>tiegħi</strong> u nħobbu ħafna.</td><td>Daniel is a great friend. He is my closest friend and I like him a lot.<br><strong>Daniel</strong> a male name<br><strong>ħabib kbir</strong> a great friend<br><strong>Huwa</strong> he<br><strong>l-akbar ħabib tiegħi</strong> my closest friend, literally &quot;biggest friend&quot;<br><strong>u nħobbu ħafna</strong> and I like him a lot; it could also read &quot;we like him a lot&quot;<br><strong>Not unique</strong> if &quot;our / their friend&quot; is meant, tagħna / tagħhom also fit a suitable context; the item alone does not decide.</td></tr><tr><td>4. Oħti <strong>għandha</strong> dar żgħira imma sabiħa.</td><td>My sister has a small but beautiful house.<br><strong>Oħti</strong> my sister<br><strong>għandha</strong> she has<br><strong>dar żgħira</strong> a small house<br><strong>imma sabiħa</strong> but beautiful, both feminine with dar.</td></tr><tr><td>5. Benjamin u l-familja <strong>tiegħu</strong> joqogħdu ġewwa Raħal Ġdid.</td><td>Benjamin and his family live in Paola.<br><strong>Benjamin</strong> a male owner<br><strong>u l-familja tiegħu</strong> and his family; it cannot become tagħha just because familja is feminine<br><strong>joqogħdu</strong> they live<br><strong>ġewwa Raħal Ġdid</strong> in Paola, literally &quot;new village&quot;.</td></tr></tbody></table><hr><h2 id="_8-colours-and-five-descriptions" tabindex="-1">8 Colours and Five Descriptions <a class="header-anchor" href="#_8-colours-and-five-descriptions" aria-label="Permalink to &quot;8 Colours and Five Descriptions&quot;">​</a></h2><h3 id="the-colour-table-completely-filled-in" tabindex="-1">The colour table, completely filled in <a class="header-anchor" href="#the-colour-table-completely-filled-in" aria-label="Permalink to &quot;The colour table, completely filled in&quot;">​</a></h3><p><code>L-Aġġettiv – Il-Kuluri</code> = the adjective — colours. <strong>Maskil</strong> masculine<br><strong>Femminil</strong> feminine. Colours usually agree with the noun they describe; some borrowings do not change.</p><table tabindex="0"><thead><tr><th>Masculine</th><th>Feminine</th><th>Chinese and notes</th></tr></thead><tbody><tr><td>abjad</td><td>bajda</td><td>white; bajda can also mean &quot;an egg&quot;, so read the context</td></tr><tr><td>iswed</td><td>sewda</td><td>black</td></tr><tr><td>aħmar</td><td>ħamra</td><td>red</td></tr><tr><td>blu / ikħal</td><td>blu / kaħla</td><td>blue; blu does not change, ikħal has kaħla</td></tr><tr><td>isfar</td><td>safra</td><td>yellow</td></tr><tr><td>aħdar</td><td>ħadra</td><td>green</td></tr><tr><td>oranġjo</td><td>oranġjo</td><td>orange</td></tr><tr><td>vjola</td><td>vjola</td><td>purple</td></tr><tr><td>kannella</td><td>kannella</td><td>brown</td></tr><tr><td>griż</td><td>griża</td><td>grey</td></tr><tr><td>ċelesti</td><td>ċelesti</td><td>sky blue</td></tr><tr><td>roża</td><td>roża</td><td>pink</td></tr><tr><td>lelà</td><td>lelà</td><td>lilac; the accent is kept</td></tr></tbody></table><h3 id="five-descriptions-full-sentences" tabindex="-1">Five descriptions, full sentences <a class="header-anchor" href="#five-descriptions-full-sentences" aria-label="Permalink to &quot;Five descriptions, full sentences&quot;">​</a></h3><p><code>Liema aġġettivi tuża biex tiddeskrivi…?</code> = which adjectives do you use to describe…? <strong>Liema aġġettivi</strong> which adjectives<br><strong>tuża</strong> you use<br><strong>biex tiddeskrivi</strong> in order to describe.</p><table tabindex="0"><thead><tr><th>Object and example sentence</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Kejk — Il-kejk taċ-ċikkulata huwa kbir, artab u ħelu, u fuq għandu frott aħmar frisk.</td><td>The chocolate cake is big, soft and sweet, and on top it has fresh red fruit.<br><strong>Il-kejk taċ-ċikkulata</strong> the chocolate cake<br><strong>huwa</strong> is<br><strong>kbir, artab u ħelu</strong> big, soft and sweet, with the masculine kejk<br><strong>u fuq għandu</strong> and on top it has<br><strong>frott aħmar frisk</strong> fresh red fruit, frott being a collective.</td></tr><tr><td>2. Tuffieħa — Din it-tuffieħa ħamra hija friska u mmerqa, għalhekk se niekolha wara l-ikla.</td><td>This red apple is fresh and juicy, so I will eat it after the meal.<br><strong>Din it-tuffieħa ħamra</strong> this red apple, feminine<br><strong>hija friska u mmerqa</strong> is fresh and juicy<br><strong>għalhekk</strong> therefore<br><strong>se niekolha</strong> I will eat it, -ha<br><strong>wara l-ikla</strong> after the meal.</td></tr><tr><td>3. Pajjiż — Dan il-pajjiż huwa żgħir iżda sabiħ, u għandu bliet antiki u kampanja ħadra.</td><td>This country is small but beautiful, and it has old cities and green countryside.<br><strong>Dan il-pajjiż</strong> this country, masculine<br><strong>huwa żgħir iżda sabiħ</strong> is small but beautiful<br><strong>u għandu</strong> and it has<br><strong>bliet antiki</strong> old cities<br><strong>u kampanja ħadra</strong> and green countryside, ħadra agreeing with kampanja.</td></tr><tr><td>4. Vaganza — Il-vaganza tagħna kienet twila u interessanti, iżda xi ġranet kienu ta’ għeja minħabba l-mixi.</td><td>Our holiday was long and interesting, but some days were tiring because of the walking.<br><strong>Il-vaganza tagħna</strong> our holiday, feminine<br><strong>kienet twila u interessanti</strong> was long and interesting<br><strong>iżda xi ġranet</strong> but some days<br><strong>kienu ta’ għeja</strong> were tiring, literally &quot;were of tiredness&quot;<br><strong>minħabba l-mixi</strong> because of the walking.</td></tr><tr><td>5. Ħabiba tiegħek — Il-ħabiba tiegħi hija ġentili, intelliġenti u paċenzjuża, u dejjem tgħinni meta jkolli problema.</td><td>My female friend is kind, intelligent and patient, and she always helps me when I have a problem.<br><strong>Il-ħabiba tiegħi</strong> my female friend<br><strong>hija ġentili</strong> she is kind<br><strong>intelliġenti</strong> intelligent<br><strong>u paċenzjuża</strong> and patient, feminine<br><strong>u dejjem tgħinni</strong> and she always helps me<br><strong>meta jkolli problema</strong> when I have a problem.</td></tr></tbody></table><hr><h2 id="_9-sixteen-plurals-and-their-type" tabindex="-1">9 Sixteen Plurals and Their Type <a class="header-anchor" href="#_9-sixteen-plurals-and-their-type" aria-label="Permalink to &quot;9 Sixteen Plurals and Their Type&quot;">​</a></h2><h3 id="the-plural-table" tabindex="-1">The plural table <a class="header-anchor" href="#the-plural-table" aria-label="Permalink to &quot;The plural table&quot;">​</a></h3><p><code>Il-Plural sħiħ u miksur – Agħti l-plural ta’ dawn in-nomi mbagħad ikteb hux sħiħ jew miksur</code> = give the plural of these nouns and then write whether it is a full or a broken plural.</p><p><strong>Il-plural</strong> the plural<br><strong>sħiħ</strong> full, i.e. formed mainly by an ending<br><strong>miksur</strong> broken, formed mainly by a change inside the word<br><strong>Agħti</strong> give<br><strong>ta’ dawn in-nomi</strong> of these nouns<br><strong>mbagħad ikteb</strong> then write<br><strong>hux … jew …</strong> whether … or ….</p><table tabindex="0"><thead><tr><th>No.</th><th>Singular → plural</th><th>Type</th><th>Chinese and formation hint</th></tr></thead><tbody><tr><td>1</td><td>lapes → lapsijiet</td><td>sħiħ</td><td>pencil; -ijiet, with a small stem adjustment</td></tr><tr><td>2</td><td>tazza → tazzi</td><td>sħiħ</td><td>cup; final a → i</td></tr><tr><td>3</td><td>raġel → rġiel</td><td>miksur</td><td>man; the vowels and structure inside the stem change</td></tr><tr><td>4</td><td>saqqu → saqqijiet</td><td>sħiħ</td><td>mattress; -ijiet</td></tr><tr><td>5</td><td>karozza → karozzi</td><td>sħiħ</td><td>car; final i</td></tr><tr><td>6</td><td>ajruplan → ajruplani</td><td>sħiħ</td><td>aeroplane; final i</td></tr><tr><td>7</td><td>mejda → imwejjed</td><td>miksur</td><td>table; mwejjed is also met, note the double j</td></tr><tr><td>8</td><td>dar → djar</td><td>miksur</td><td>house; internal change</td></tr><tr><td>9</td><td>kċina → kċejjen</td><td>miksur</td><td>kitchen; internal vowel change</td></tr><tr><td>10</td><td>ikla → ikliet</td><td>sħiħ</td><td>meal; -iet</td></tr><tr><td>11</td><td>dgħajsa → dgħajjes</td><td>miksur</td><td>small boat; internal change</td></tr><tr><td>12</td><td>siġra → siġar</td><td>miksur</td><td>tree; the usual plural is siġar, while the counting form siġriet is also a full plural and must be distinguished</td></tr><tr><td>13</td><td>furketta → frieket</td><td>miksur</td><td>fork; internal change</td></tr><tr><td>14</td><td>stilla → stilel</td><td>miksur</td><td>star; internal change</td></tr><tr><td>15</td><td>xogħol → xogħlijiet</td><td>sħiħ</td><td>work, works, construction; -ijiet</td></tr><tr><td>16</td><td>xahar → xhur</td><td>miksur</td><td>month; internal vowel change</td></tr></tbody></table><p>&quot;Full plural&quot; does not mean &quot;the word never changes and only a letter is glued on the end&quot;; <strong>lapes → lapsijiet</strong>, for instance, adjusts the stem but is still classified by its suffix. Some nouns have several plurals with different meanings or counting conditions, so this table is not an exclusive dictionary.</p><hr><h2 id="_10-two-tasks-plural-columns-and-numbers-with-prepositions" tabindex="-1">10 Two Tasks: Plural Columns and Numbers with Prepositions <a class="header-anchor" href="#_10-two-tasks-plural-columns-and-numbers-with-prepositions" aria-label="Permalink to &quot;10 Two Tasks: Plural Columns and Numbers with Prepositions&quot;">​</a></h2><h3 id="task-one-the-plural-columns" tabindex="-1">Task one: the plural columns <a class="header-anchor" href="#task-one-the-plural-columns" aria-label="Permalink to &quot;Task one: the plural columns&quot;">​</a></h3><p><code>Issepara l-kliem f’kolonni differenti skont jiġux iffurmati fil-plural permezz ta’ suffiss jew inkella permezz ta’ bidla interna. Fil-kolonni ikteb biss il-kelma fil-plural.</code></p><p>Translation: separate the words into different columns according to whether their plural is formed by a suffix or by an internal change; write only the plural word in the columns.</p><p><strong>Issepara</strong> separate<br><strong>l-kliem</strong> the words<br><strong>f’kolonni differenti</strong> in different columns<br><strong>skont</strong> according to<br><strong>jiġux iffurmati</strong> whether they are formed<br><strong>fil-plural</strong> in the plural<br><strong>permezz ta’ suffiss</strong> by means of a suffix<br><strong>jew inkella</strong> or else<br><strong>permezz ta’ bidla interna</strong> by means of an internal change<br><strong>Fil-kolonni</strong> in the columns<br><strong>ikteb biss</strong> write only<br><strong>il-kelma fil-plural</strong> the word in the plural.</p><table tabindex="0"><thead><tr><th>Full plural: only these words</th><th>Broken plural: only these words</th></tr></thead><tbody><tr><td>fletts<br>muntanji<br>roti<br>vaski<br>laptops<br>pumijiet<br>lasti<br>ġebliet</td><td>rġiel<br>btieħi<br>klieb<br>ibħra<br>ħnieżer<br>xbieki<br>subien</td></tr></tbody></table><p><strong>widnejn</strong> is listed separately: widna (ear) → widnejn (both ears / ears), a historical dual or paired form that the two-way division of the task cannot fully cover. If the teacher puts -ejn forms with the suffix class, follow the class marking while keeping this grammatical difference and not calling it a typical broken plural.</p><table tabindex="0"><thead><tr><th>Original word pair</th><th>Chinese and analysis</th></tr></thead><tbody><tr><td>raġel – rġiel</td><td>man, singular / plural</td></tr><tr><td>flett – fletts</td><td>flat, English-style -s suffix</td></tr><tr><td>muntanja – muntanji</td><td>mountain, ending changed to i</td></tr><tr><td>bitħa – btieħi</td><td>courtyard, internal change</td></tr><tr><td>kelb – klieb</td><td>dog, internal change</td></tr><tr><td>rota – roti</td><td>bicycle, final i</td></tr><tr><td>baħar – ibħra</td><td>sea, internal change</td></tr><tr><td>ħanżir – ħnieżer</td><td>pig, internal change</td></tr><tr><td>vaska – vaski</td><td>bathtub / sink, final i</td></tr><tr><td>xibka – xbieki</td><td>net, internal change</td></tr><tr><td>widna – widnejn</td><td>ear / both ears, historical dual</td></tr><tr><td>laptop – laptops</td><td>laptop, -s</td></tr><tr><td>tifel – subien</td><td>boy / boys; subien specifically means boys, while tifel meaning &quot;child&quot; usually pluralises as tfal</td></tr><tr><td>pum – pumijiet</td><td>knob, handle; -ijiet</td></tr><tr><td>lasta – lasti</td><td>pole, final i</td></tr><tr><td>ġebla – ġebliet</td><td>stone, -iet; distinct from the collective ġebel</td></tr></tbody></table><h3 id="task-two-ten-items-with-numbers-and-prepositions" tabindex="-1">Task two: ten items with numbers and prepositions <a class="header-anchor" href="#task-two-ten-items-with-numbers-and-prepositions" aria-label="Permalink to &quot;Task two: ten items with numbers and prepositions&quot;">​</a></h3><p><code>In-Numri u l-Prepożizzjonijiet – Imla l-vojt</code> = numbers and prepositions — fill in the blank. <strong>In-numri</strong> numbers<br><strong>il-prepożizzjonijiet</strong> prepositions. Without a picture or full context the spatial preposition is not the only answer; the sentences below form one coherent set.</p><table tabindex="0"><thead><tr><th>Full model sentence</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. <strong>Fuq</strong> l-iskrivanija għandi <strong>żewġ</strong> kotba, <strong>tliet</strong> lapsijiet u <strong>ħames</strong> fajls.</td><td>On the desk I have two books, three pencils and five folders.<br><strong>Fuq l-iskrivanija</strong> on the desk<br><strong>għandi</strong> I have<br><strong>żewġ kotba</strong> two books<br><strong>tliet lapsijiet</strong> three pencils<br><strong>u ħames fajls</strong> and five folders.</td></tr><tr><td>2. Il-qattus raqad <strong>fuq</strong> is-sodda, <strong>b’erba’</strong> kutri fuqu.</td><td>The cat slept on the bed with four blankets on it.<br><strong>Il-qattus</strong> the cat<br><strong>raqad</strong> slept<br><strong>fuq is-sodda</strong> on the bed<br><strong>b’erba’ kutri</strong> with four blankets<br><strong>fuqu</strong> on it, fuq + u.</td></tr><tr><td>3. <strong>Quddiem</strong> id-dar hemm <strong>seba’</strong> siġriet.</td><td>In front of the house there are seven trees.<br><strong>Quddiem</strong> in front; ħdejn &quot;next to&quot; also fits another situation<br><strong>id-dar</strong> the house<br><strong>hemm</strong> there is / there are<br><strong>seba’ siġriet</strong> seven trees, counting plural.</td></tr><tr><td>4. <strong>Ħdejn il-knisja</strong> fetħu <strong>sitt</strong> iħwienet ġodda.</td><td>Next to the church they opened six new shops.<br><strong>Ħdejn il-knisja</strong> next to the church; the textbook&#39;s l-knisja takes the article when joined to the chosen preposition<br><strong>fetħu</strong> they opened<br><strong>sitt iħwienet</strong> six shops<br><strong>ġodda</strong> new, plural.</td></tr><tr><td>5. <strong>Għoxrin</strong> student applikaw għall-kors.</td><td>Twenty students applied for the course.<br><strong>Għoxrin student</strong> twenty students, the noun stays singular after the numeral<br><strong>applikaw</strong> they applied, the predicate is plural<br><strong>għall-kors</strong> for the course.</td></tr><tr><td>6. <strong>Fuq</strong> l-ajruplan konna <strong>tmenin</strong> ruħ.</td><td>On the plane we were eighty people.<br><strong>Fuq l-ajruplan</strong> on the plane, also ġewwa l-ajruplan<br><strong>konna</strong> we were<br><strong>tmenin</strong> eighty<br><strong>ruħ</strong> people, literally souls, used when counting persons.</td></tr><tr><td>7. <strong>Iż-żewġt</strong> itfal staħbew <strong>wara</strong> il-purtieri.</td><td>The two children hid behind the curtains.<br><strong>Iż-żewġt itfal</strong> the two children; żewġt is used before a vowel-initial noun<br><strong>staħbew</strong> they hid<br><strong>wara</strong> behind<br><strong>il-purtieri</strong> the curtains.</td></tr><tr><td>8. Il-ħanut tal-merċa jinsab <strong>bejn</strong> tal-laħam u tal-ħwejjeġ.</td><td>The grocery is between the butcher&#39;s and the clothes shop.<br><strong>Il-ħanut tal-merċa</strong> the grocery<br><strong>jinsab</strong> is located<br><strong>bejn</strong> between<br><strong>tal-laħam</strong> the butcher&#39;s, with il-ħanut omitted<br><strong>u tal-ħwejjeġ</strong> and the clothes shop.</td></tr><tr><td>9. Daħħal il-kejk <strong>fil-forn</strong> u agħmel it-temperatura fuq <strong>mija u ħamsa u sebgħin</strong> gradi <strong>Celsius</strong>.</td><td>Put the cake in the oven and set the temperature to 175 degrees Celsius.<br><strong>Daħħal</strong> put in, imperative<br><strong>il-kejk</strong> the cake<br><strong>fil-forn</strong> in / into the oven, fi + the article<br><strong>u agħmel</strong> and set<br><strong>it-temperatura fuq</strong> the temperature at<br><strong>mija u ħamsa u sebgħin</strong> 175, literally one hundred and five and seventy<br><strong>gradi Celsius</strong> degrees Celsius; the textbook&#39;s celcius spelling is corrected.</td></tr><tr><td>10. Il-basket l-iswed jiswa <strong>ħamsa u ħamsin</strong> ewro.</td><td>The black bag costs 55 euros.<br><strong>Il-basket l-iswed</strong> the black bag, the article repeated on noun and adjective<br><strong>jiswa</strong> costs, is worth<br><strong>ħamsa u ħamsin</strong> 55, five and fifty<br><strong>ewro</strong> euro.</td></tr></tbody></table><hr><h2 id="_11-the-twelve-months" tabindex="-1">11 The Twelve Months <a class="header-anchor" href="#_11-the-twelve-months" aria-label="Permalink to &quot;11 The Twelve Months&quot;">​</a></h2><h3 id="one-fuller-sentence-for-each-month" tabindex="-1">One fuller sentence for each month <a class="header-anchor" href="#one-fuller-sentence-for-each-month" aria-label="Permalink to &quot;One fuller sentence for each month&quot;">​</a></h3><p><code>Ix-Xhur – Ikteb sentenza dwar kull xahar</code> = the months — write a sentence about each month. <strong>Ix-xhur</strong> the months, plural<br><strong>Ikteb sentenza</strong> write a sentence<br><strong>dwar kull xahar</strong> about each month. The arrangements below are model everyday plans; the weather is not a guarantee for every year or month.</p><table tabindex="0"><thead><tr><th>Month and sentence</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. <strong>Jannar</strong> — F’Jannar nibda sena ġdida billi nagħmel pjan għall-istudju u nipprova nqatta’ aktar ħin mal-familja.</td><td>In January I start a new year by making a study plan and try to spend more time with the family.<br><strong>F’Jannar</strong> in January<br><strong>nibda sena ġdida</strong> I start a new year<br><strong>billi nagħmel pjan</strong> by making a plan<br><strong>għall-istudju</strong> for study<br><strong>u nipprova</strong> and I try<br><strong>nqatta’ aktar ħin</strong> to spend more time<br><strong>mal-familja</strong> with the family.</td></tr><tr><td>2. <strong>Frar</strong> — Fi Frar, meta jkun il-bard, inħobb insajjar soppa sħuna u naqra ktieb tajjeb id-dar.</td><td>In February, when it is cold, I like cooking a hot soup and reading a good book at home.<br><strong>Fi Frar</strong> in February<br><strong>meta jkun il-bard</strong> when it is cold<br><strong>inħobb insajjar</strong> I like to cook<br><strong>soppa sħuna</strong> a hot soup<br><strong>u naqra ktieb tajjeb</strong> and read a good book<br><strong>id-dar</strong> at home.</td></tr><tr><td>3. <strong>Marzu</strong> — F’Marzu nimxi fil-kampanja ma’ sħabi u nieħu ritratti tal-fjuri li jibdew jidhru matul ir-rebbiegħa.</td><td>In March I walk in the countryside with my friends and take photos of the flowers that start to appear during spring.<br><strong>F’Marzu</strong> in March<br><strong>nimxi fil-kampanja</strong> I walk in the countryside<br><strong>ma’ sħabi</strong> with my friends<br><strong>u nieħu ritratti</strong> and I take photos<br><strong>tal-fjuri</strong> of the flowers<br><strong>li jibdew jidhru</strong> that start to show<br><strong>matul ir-rebbiegħa</strong> during spring.</td></tr><tr><td>4. <strong>April</strong> — F’April nixtieq nieħu ftit jiem vaganza biex inżur belt ġdida u nitgħallem aktar dwar l-istorja tagħha.</td><td>In April I want to take a few days of holiday to visit a new city and learn more about its history.<br><strong>F’April</strong> in April<br><strong>nixtieq nieħu</strong> I want to take<br><strong>ftit jiem vaganza</strong> a few days of holiday<br><strong>biex inżur</strong> in order to visit<br><strong>belt ġdida</strong> a new city, feminine<br><strong>u nitgħallem aktar</strong> and learn more<br><strong>dwar l-istorja tagħha</strong> about its history.</td></tr><tr><td>5. <strong>Mejju</strong> — F’Mejju normalment nistudja aktar filgħaxija għax irrid inkun ippreparat għall-eżamijiet li jkolli fl-aħħar tal-kors.</td><td>In May I usually study more in the evening because I want to be prepared for the exams I will have at the end of the course.<br><strong>F’Mejju</strong> in May<br><strong>normalment nistudja aktar</strong> I usually study more<br><strong>filgħaxija</strong> in the evening<br><strong>għax irrid inkun ippreparat</strong> because I want to be prepared, masculine; feminine ippreparata<br><strong>għall-eżamijiet</strong> for the exams<br><strong>li jkolli</strong> that I will have<br><strong>fl-aħħar tal-kors</strong> at the end of the course.</td></tr><tr><td>6. <strong>Ġunju</strong> — F’Ġunju l-ġranet ikunu twal, u wara x-xogħol kultant immur il-baħar biex ngħum u nistrieħ.</td><td>In June the days are long, and after work I sometimes go to the sea to swim and rest.<br><strong>F’Ġunju</strong> in June<br><strong>l-ġranet ikunu twal</strong> the days are usually long<br><strong>u wara x-xogħol</strong> and after work<br><strong>kultant immur il-baħar</strong> sometimes I go to the sea<br><strong>biex ngħum u nistrieħ</strong> in order to swim and rest.</td></tr><tr><td>7. <strong>Lulju</strong> — F’Lulju nippreferi noħroġ kmieni filgħodu, nieħu l-ilma miegħi u nevita mixjiet twal fix-xemx ta’ nofsinhar.</td><td>In July I prefer to go out early in the morning, take water with me and avoid long walks in the midday sun.<br><strong>F’Lulju</strong> in July<br><strong>nippreferi noħroġ</strong> I prefer to go out<br><strong>kmieni filgħodu</strong> early in the morning<br><strong>nieħu l-ilma miegħi</strong> I take the water with me<br><strong>u nevita</strong> and I avoid<br><strong>mixjiet twal</strong> long walks<br><strong>fix-xemx ta’ nofsinhar</strong> in the midday sun.</td></tr><tr><td>8. <strong>Awwissu</strong> — F’Awwissu nqatta’ aktar ħin mal-ħbieb ħdejn il-baħar u nħobb niekol xi ħaġa ħafifa wara l-għawm.</td><td>In August I spend more time with friends by the sea and I like eating something light after swimming.<br><strong>F’Awwissu</strong> in August<br><strong>nqatta’ aktar ħin</strong> I spend more time<br><strong>mal-ħbieb</strong> with friends<br><strong>ħdejn il-baħar</strong> by the sea<br><strong>u nħobb niekol</strong> and I like to eat<br><strong>xi ħaġa ħafifa</strong> something light<br><strong>wara l-għawm</strong> after swimming.</td></tr><tr><td>9. <strong>Settembru</strong> — F’Settembru nerġa’ nibda l-kors tal-Malti u nirrevedi n-noti tiegħi biex niftakar dak li tgħallimt qabel is-sajf.</td><td>In September I start the Maltese course again and review my notes to remember what I learnt before the summer.<br><strong>F’Settembru</strong> in September<br><strong>nerġa’ nibda</strong> I start again<br><strong>l-kors tal-Malti</strong> the Maltese course<br><strong>u nirrevedi n-noti tiegħi</strong> and I review my notes<br><strong>biex niftakar</strong> in order to remember<br><strong>dak li tgħallimt</strong> what I learnt<br><strong>qabel is-sajf</strong> before the summer.</td></tr><tr><td>10. <strong>Ottubru</strong> — F’Ottubru nħobb inżur mużew ma’ ħabib u wara noqogħdu f’kafetterija nitkellmu dwar dak li rajna.</td><td>In October I like visiting a museum with a friend and afterwards we sit in a café talking about what we saw.<br><strong>F’Ottubru</strong> in October<br><strong>nħobb inżur mużew</strong> I like to visit a museum<br><strong>ma’ ħabib</strong> with a friend<br><strong>u wara</strong> and afterwards<br><strong>noqogħdu f’kafetterija</strong> we sit in a café<br><strong>nitkellmu dwar</strong> we talk about<br><strong>dak li rajna</strong> what we saw.</td></tr><tr><td>11. <strong>Novembru</strong> — F’Novembru, jekk tkun ix-xita, nibqa’ d-dar u nuża l-ħin biex nistudja, insajjar u nċempel lill-familja.</td><td>In November, if it rains, I stay at home and use the time to study, cook and call the family.<br><strong>F’Novembru</strong> in November<br><strong>jekk tkun ix-xita</strong> if it is raining<br><strong>nibqa’ d-dar</strong> I stay at home<br><strong>u nuża l-ħin</strong> and I use the time<br><strong>biex nistudja</strong> in order to study<br><strong>insajjar</strong> to cook<br><strong>u nċempel lill-familja</strong> and to call the family.</td></tr><tr><td>12. <strong>Diċembru</strong> — F’Diċembru niltaqa’ mal-familja għall-festi, ngħin fit-tisjir u nħejji rigali żgħar għall-persuni li nħobb.</td><td>In December I meet the family for the holidays, help with the cooking and prepare small gifts for the people I love.<br><strong>F’Diċembru</strong> in December<br><strong>niltaqa’ mal-familja</strong> I meet the family<br><strong>għall-festi</strong> for the holidays<br><strong>ngħin fit-tisjir</strong> I help with cooking<br><strong>u nħejji</strong> and I prepare<br><strong>rigali żgħar</strong> small gifts<br><strong>għall-persuni li nħobb</strong> for the people I love.</td></tr></tbody></table><hr><h2 id="_12-eight-occupations-pictures-and-sentences" tabindex="-1">12 Eight Occupations: Pictures and Sentences <a class="header-anchor" href="#_12-eight-occupations-pictures-and-sentences" aria-label="Permalink to &quot;12 Eight Occupations: Pictures and Sentences&quot;">​</a></h2><h3 id="the-pictures-and-model-sentences" tabindex="-1">The pictures and model sentences <a class="header-anchor" href="#the-pictures-and-model-sentences" aria-label="Permalink to &quot;The pictures and model sentences&quot;">​</a></h3><p><code>L-impjiegi</code> = jobs / occupations. <code>Ikteb il-professjoni ta’ dawn il-persuni taħt l-istampa</code> = write the profession of these people under the picture. <strong>Ikteb</strong> write<br><strong>il-professjoni</strong> the profession<br><strong>ta’ dawn il-persuni</strong> of these people<br><strong>taħt l-istampa</strong> under the picture. The English prompt <code>Write down the profession of these persons under their picture</code> means the same.</p><p>The pictures are read from top to bottom and left to right in each row; there is also an office photo at the top right which does not count as a further blank. A picture cannot prove a person&#39;s real identity, so the answers below rely on the obvious tools and setting.</p><table tabindex="0"><thead><tr><th>No., job and full sentence</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. <strong>tabib</strong> — It-tabib jara lill-pazjenti fil-klinika u jispjegalhom kif għandhom jieħdu l-mediċina tagħhom.</td><td>The doctor sees the patients in the clinic and explains to them how they should take their medicine.<br><strong>It-tabib</strong> the male doctor; a female doctor is tabiba<br><strong>jara lill-pazjenti</strong> sees the patients<br><strong>fil-klinika</strong> in the clinic<br><strong>u jispjegalhom</strong> and explains to them<br><strong>kif għandhom jieħdu</strong> how they should take<br><strong>l-mediċina tagħhom</strong> their medicine.</td></tr><tr><td>2. <strong>ħaddiema tat-tindif</strong> — Il-ħaddiema tat-tindif tnaddaf l-art u l-kmamar biex l-uffiċċju jkun nadif qabel jaslu l-impjegati.</td><td>The cleaner cleans the floor and the rooms so that the office is clean before the employees arrive.<br><strong>Il-ħaddiema tat-tindif</strong> the cleaner; the same form can also be plural, here tnaddaf makes it one female cleaner<br><strong>tnaddaf l-art u l-kmamar</strong> she cleans the floor and the rooms<br><strong>biex l-uffiċċju jkun nadif</strong> so that the office is clean<br><strong>qabel jaslu l-impjegati</strong> before the employees arrive<br><strong>Also acceptable</strong> seftura can be said for a domestic worker, but the picture does not settle the employment.</td></tr><tr><td>3. <strong>għalliem</strong> — L-għalliem jispjega l-lezzjoni fuq il-bord u jagħti eżempji biex it-tfal jifhmu aħjar.</td><td>The teacher explains the lesson on the board and gives examples so that the children understand better.<br><strong>L-għalliem</strong> the male teacher; a female teacher is għalliema<br><strong>jispjega l-lezzjoni</strong> explains the lesson<br><strong>fuq il-bord</strong> on the board<br><strong>u jagħti eżempji</strong> and gives examples<br><strong>biex it-tfal</strong> so that the children<br><strong>jifhmu aħjar</strong> understand better.</td></tr><tr><td>4. <strong>pittur</strong> — Il-pittur juża ħafna kuluri biex ipinġi veduta tal-baħar li se juriha f’wirja.</td><td>The painter uses many colours to paint a sea view that he will show in an exhibition.<br><strong>Il-pittur</strong> the male painter; a female painter is pittriċi<br><strong>juża ħafna kuluri</strong> uses many colours<br><strong>biex ipinġi</strong> in order to paint<br><strong>veduta tal-baħar</strong> a sea view<br><strong>li se juriha</strong> that he will show, -ha refers to the view<br><strong>f’wirja</strong> in an exhibition.</td></tr><tr><td>5. <strong>bejjiegħa tal-ġelat</strong> — Il-bejjiegħa tal-ġelat isservi lit-tfal fil-pjazza u tistaqsihom liema togħma jippreferu.</td><td>The ice-cream seller serves the children in the square and asks them which flavour they prefer.<br><strong>Il-bejjiegħa tal-ġelat</strong> the female ice-cream seller<br><strong>isservi lit-tfal</strong> serves the children<br><strong>fil-pjazza</strong> in the square<br><strong>u tistaqsihom</strong> and asks them<br><strong>liema togħma jippreferu</strong> which flavour they prefer<br><strong>Alternative name</strong> ġelatiera can also be used for this job; the descriptive phrase is used here because the picture is ambiguous.</td></tr><tr><td>6. <strong>kantanta</strong> — Il-kantanta tkanta fuq il-palk ma’ grupp ta’ mużiċisti waqt kunċert għall-familji.</td><td>The singer sings on stage with a group of musicians during a concert for families.<br><strong>Il-kantanta</strong> the female singer; a male singer is kantant<br><strong>tkanta</strong> she sings<br><strong>fuq il-palk</strong> on stage<br><strong>ma’ grupp ta’ mużiċisti</strong> with a group of musicians<br><strong>waqt kunċert</strong> during a concert<br><strong>għall-familji</strong> for families.</td></tr><tr><td>7. <strong>bidwi</strong> — Il-bidwi jaħdem fl-għalqa kmieni filgħodu u jkabbar ħaxix frisk biex ibigħu fis-suq.</td><td>The farmer works in the field early in the morning and grows fresh vegetables to sell them at the market.<br><strong>Il-bidwi</strong> the male farmer; a female farmer is bidwija<br><strong>jaħdem fl-għalqa</strong> works in the field<br><strong>kmieni filgħodu</strong> early in the morning<br><strong>u jkabbar ħaxix frisk</strong> and grows fresh vegetables<br><strong>biex ibigħu</strong> in order to sell it, -u refers to the collective ħaxix<br><strong>fis-suq</strong> at the market.</td></tr><tr><td>8. <strong>attur</strong> — L-attur jitgħallem il-kliem tiegħu u jipprattika ma’ sħabu qabel l-ispettaklu fit-teatru.</td><td>The actor learns his lines and rehearses with his colleagues before the performance in the theatre.<br><strong>L-attur</strong> the male actor; a female actor is attriċi<br><strong>jitgħallem il-kliem tiegħu</strong> learns his lines<br><strong>u jipprattika</strong> and rehearses<br><strong>ma’ sħabu</strong> with his companions<br><strong>qabel l-ispettaklu</strong> before the performance<br><strong>fit-teatru</strong> in the theatre.</td></tr></tbody></table><hr><h2 id="_13-the-occupation-crossword-ten-items" tabindex="-1">13 The Occupation Crossword: Ten Items <a class="header-anchor" href="#_13-the-occupation-crossword-ten-items" aria-label="Permalink to &quot;13 The Occupation Crossword: Ten Items&quot;">​</a></h2><h3 id="clues-answers-and-breakdown" tabindex="-1">Clues, answers and breakdown <a class="header-anchor" href="#clues-answers-and-breakdown" aria-label="Permalink to &quot;Clues, answers and breakdown&quot;">​</a></h3><p><code>It-tisliba dwar l-impjiegi</code> = the crossword about occupations. <strong>it-tisliba</strong> the crossword<br><strong>dwar</strong> about<br><strong>l-impjiegi</strong> occupations.</p><p>Lengths below count each written letter; none of the answers in this set has the two-letter għ problem. As in the picture: 1, 2, 3, 4, 7 and 9 go down; 5, 6, 8 and 10 go across; 3 and 6 share the starting b.</p><table tabindex="0"><thead><tr><th>No., full clue</th><th>Answer, Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Jien insajjar fil-kċina. / I cook in the kitchen.</td><td><strong>kok</strong>, 3 letters, cook.<br><strong>Jien</strong> I<br><strong>insajjar</strong> I cook<br><strong>fil-kċina</strong> in the kitchen.</td></tr><tr><td>2. Jien nagħti l-injezzjonijiet u l-pilloli lill-pazjenti. / I give injections and pills to patients.</td><td><strong>ners</strong>, 4 letters, nurse.<br><strong>Jien nagħti</strong> I give<br><strong>l-injezzjonijiet</strong> the injections<br><strong>u l-pilloli</strong> and the pills<br><strong>lill-pazjenti</strong> to the patients<br><strong>Distinction</strong> tabib may do some of this too, but five letters do not fit this slot.</td></tr><tr><td>3. Jien nibni d-djar. / I build houses.</td><td><strong>bennej</strong>, 6 letters, builder / mason.<br><strong>Jien</strong> I<br><strong>nibni</strong> I build<br><strong>d-djar</strong> the houses.</td></tr><tr><td>4. Jien inżomm l-ordni fis-soċjetà. / I maintain order in society.</td><td><strong>pulizija</strong>, 8 letters, police officer.<br><strong>Jien inżomm</strong> I maintain<br><strong>l-ordni</strong> the order<br><strong>fis-soċjetà</strong> in society.</td></tr><tr><td>5. Jien nassigura li l-pajjiż huwa protett u sigur. / I ensure the protection and safety of a country.</td><td><strong>suldat</strong>, 6 letters, soldier.<br><strong>Jien nassigura</strong> I ensure<br><strong>li</strong> that<br><strong>l-pajjiż</strong> the country<br><strong>huwa protett</strong> is protected<br><strong>u sigur</strong> and safe.</td></tr><tr><td>6. Jien insuq l-ajruplani. / I drive airplanes.</td><td><strong>bdot</strong>, 4 letters, pilot.<br><strong>Jien insuq</strong> I drive<br><strong>l-ajruplani</strong> the aeroplanes<br><strong>Distinction</strong> pilota is a synonym for the job but has a different length; this slot shares b with bennej.</td></tr><tr><td>7. Jien inqassam l-ittri d-dar. / I post letters in houses.</td><td><strong>pustier</strong>, 7 letters, postman.<br><strong>Jien inqassam</strong> I distribute<br><strong>l-ittri</strong> the letters<br><strong>d-dar</strong> to the house, the textbook&#39;s elliptical phrasing.</td></tr><tr><td>8. Jien nibni l-għamara bl-injam. / I build furniture using wood.</td><td><strong>mastrudaxxa</strong>, 11 letters, carpenter.<br><strong>Jien nibni</strong> I build / make<br><strong>l-għamara</strong> the furniture<br><strong>bl-injam</strong> with wood, bi + the article.</td></tr><tr><td>9. Jien niddefendi n-nies fil-qorti. / I defend people in court.</td><td><strong>avukat</strong>, 6 letters, lawyer.<br><strong>Jien niddefendi</strong> I defend<br><strong>n-nies</strong> the people<br><strong>fil-qorti</strong> in court.</td></tr><tr><td>10. Jien norganizza l-appuntament u l-karti ta’ persuni importanti. / I organise appointments and papers for people.</td><td><strong>segretarju</strong>, 10 letters, secretary.<br><strong>Jien norganizza</strong> I organise<br><strong>l-appuntament</strong> the appointment, singular in Maltese while the English clue uses the plural appointments<br><strong>u l-karti</strong> and the papers<br><strong>ta’ persuni importanti</strong> of important people; the English clue is briefer.</td></tr></tbody></table><hr><h2 id="_14-sara-s-diary-full-text-and-narrative-order" tabindex="-1">14 Sara&#39;s Diary: Full Text and Narrative Order <a class="header-anchor" href="#_14-sara-s-diary-full-text-and-narrative-order" aria-label="Permalink to &quot;14 Sara&#39;s Diary: Full Text and Narrative Order&quot;">​</a></h2><h3 id="the-diary-sentence-by-sentence" tabindex="-1">The diary, sentence by sentence <a class="header-anchor" href="#the-diary-sentence-by-sentence" aria-label="Permalink to &quot;The diary, sentence by sentence&quot;">​</a></h3><p><code>Il-Qari – Aqra din is-silta u wieġeb il-mistoqsijiet</code> = reading — read this passage and answer the questions. <strong>Aqra</strong> read<br><strong>din is-silta</strong> this passage<br><strong>u wieġeb</strong> and answer<br><strong>il-mistoqsijiet</strong> the questions. <code>Id-djarju ta’ Sara</code> = Sara&#39;s diary; <strong>id-djarju</strong> the diary<br><strong>ta’ Sara</strong> Sara&#39;s.</p><table tabindex="0"><thead><tr><th>Original sentence</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>Nhar il-Ħadd li għadda ħriġt mal-familja tiegħi.</td><td>Last Sunday I went out with my family.<br><strong>Nhar il-Ħadd</strong> on Sunday<br><strong>li għadda</strong> that passed<br><strong>ħriġt</strong> I went out<br><strong>mal-familja tiegħi</strong> with my family.</td></tr><tr><td>Kienet xemx tisreġ u ħafna sħana, għalhekk ilbist libsa ħafifa u żanżant sandli ġdid.</td><td>The sun was blazing and it was very hot, so I put on a light dress and wore new sandals for the first time.<br><strong>Kienet</strong> it was<br><strong>xemx tisreġ</strong> a blazing sun, a fixed description<br><strong>u ħafna sħana</strong> and a lot of heat<br><strong>għalhekk</strong> so<br><strong>ilbist</strong> I put on<br><strong>libsa ħafifa</strong> a light dress<br><strong>u żanżant</strong> and I wore new footwear for the first time, not simply &quot;bought&quot;<br><strong>sandli ġdid</strong> new sandals, keeping the textbook&#39;s form.</td></tr><tr><td>Oħti libset flokk abjad bil-komma qasira u qalziet blu.</td><td>My sister put on a white short-sleeved top and blue trousers.<br><strong>Oħti</strong> my sister<br><strong>libset</strong> she put on<br><strong>flokk abjad</strong> a white top<br><strong>bil-komma qasira</strong> with a short sleeve<br><strong>u qalziet blu</strong> and blue trousers.</td></tr><tr><td>Ommi libset blaws roża u dublett iswed sal-irkoppa.</td><td>My mother put on a pink blouse and a black knee-length skirt.<br><strong>Ommi</strong> my mother<br><strong>libset</strong> she put on<br><strong>blaws roża</strong> a pink blouse<br><strong>u dublett iswed</strong> and a black skirt<br><strong>sal-irkoppa</strong> down to the knee, sa + the article.</td></tr><tr><td>Missieri libes qmis safra u qalziet iswed.</td><td>My father put on a yellow shirt and black trousers.<br><strong>Missieri</strong> my father<br><strong>libes</strong> he put on<br><strong>qmis safra</strong> a yellow shirt, qmis being feminine<br><strong>u qalziet iswed</strong> and black trousers, here with a masculine adjective.</td></tr><tr><td>Fl-għaxra ta’ filgħodu konna lesti u qbadna t-triq lejn iż-Żurrieq.</td><td>At ten in the morning we were ready and set off on the road to Żurrieq.<br><strong>Fl-għaxra ta’ filgħodu</strong> at ten in the morning<br><strong>konna lesti</strong> we were ready<br><strong>u qbadna t-triq</strong> and we set off, literally &quot;we grabbed the road&quot;<br><strong>lejn iż-Żurrieq</strong> towards Żurrieq, a place name.</td></tr><tr><td>Hemm rajna veduta mill-isbaħ tal-baħar u l-wied, kif ukoll ta’ Filfla!</td><td>There we saw a most beautiful view of the sea and the valley, and also of Filfla!<br><strong>Hemm</strong> there<br><strong>rajna</strong> we saw<br><strong>veduta mill-isbaħ</strong> a most beautiful view<br><strong>tal-baħar u l-wied</strong> of the sea and the valley<br><strong>kif ukoll</strong> as well as<br><strong>ta’ Filfla</strong> of Filfla, the island&#39;s name.</td></tr><tr><td>Wara soqna lejn is-Siġġiewi u smajna quddies fil-knisja parrokkjali.</td><td>Then we drove to Siġġiewi and attended Mass in the parish church.<br><strong>Wara</strong> afterwards<br><strong>soqna</strong> we drove<br><strong>lejn is-Siġġiewi</strong> towards Siġġiewi<br><strong>u smajna quddies</strong> and we attended Mass, literally &quot;heard Mass&quot;<br><strong>fil-knisja parrokkjali</strong> in the parish church.</td></tr><tr><td>Wara l-quddies kien sar il-ħin għall-ikla ta’ nofsinhar u morna f’restorant Ħad-Dingli għall-veduta tal-irdum.</td><td>After Mass it was time for the midday meal and we went to a restaurant in Dingli for the view of the cliff.<br><strong>Wara l-quddies</strong> after Mass<br><strong>kien sar il-ħin</strong> the time had come<br><strong>għall-ikla ta’ nofsinhar</strong> for the midday meal<br><strong>u morna f’restorant</strong> and we went to a restaurant<br><strong>Ħad-Dingli</strong> in Dingli<br><strong>għall-veduta tal-irdum</strong> for the cliff view.</td></tr><tr><td>Jien u oħti ordnajna platt għaġin biż-zalza ħamra u ommi u missieri ħadu biċċa laħam bil-patata.</td><td>My sister and I ordered a plate of pasta with red sauce, and my mother and father had a piece of meat with potatoes.<br><strong>Jien u oħti</strong> my sister and I<br><strong>ordnajna</strong> we ordered<br><strong>platt għaġin</strong> a plate of pasta<br><strong>biż-zalza ħamra</strong> with red sauce<br><strong>u ommi u missieri</strong> and my mother and father<br><strong>ħadu</strong> they took / had<br><strong>biċċa laħam</strong> a piece of meat<br><strong>bil-patata</strong> with potatoes.</td></tr><tr><td>L-ikel kien veru tajjeb!</td><td>The food was really good!<br><strong>L-ikel</strong> the food<br><strong>kien</strong> it was<br><strong>veru</strong> really<br><strong>tajjeb</strong> good, tasty.</td></tr><tr><td>Waqt li kont qed niekol, ċappast il-libsa biż-zalza u oħti qagħdet tidħak bija għax tgħidli li ma nafx niekol.</td><td>While I was eating I got sauce on my dress, and my sister kept laughing at me because she told me I do not even know how to eat.<br><strong>Waqt li</strong> while<br><strong>kont qed niekol</strong> I was eating<br><strong>ċappast</strong> I stained<br><strong>il-libsa</strong> the dress<br><strong>biż-zalza</strong> with the sauce<br><strong>u oħti</strong> and my sister<br><strong>qagħdet tidħak bija</strong> she kept laughing at me, bija = at me<br><strong>għax tgħidli</strong> because she says to me<br><strong>li ma nafx niekol</strong> that I do not know how to eat.</td></tr><tr><td>Wara l-ikel morna mixja mal-irdum u xtrajna ġelat.</td><td>After the meal we went for a walk along the cliff and bought ice cream.<br><strong>Wara l-ikel</strong> after the meal<br><strong>morna mixja</strong> we went for a walk<br><strong>mal-irdum</strong> along the cliff<br><strong>u xtrajna ġelat</strong> and we bought ice cream.</td></tr><tr><td>Xi t-tlieta ta’ waranofsinhar soqna għal Ħ’Attard u żorna ftit lin-nanna.</td><td>At about three in the afternoon we drove to Attard and visited grandmother for a while.<br><strong>Xi t-tlieta</strong> about three, xi marking approximation<br><strong>ta’ waranofsinhar</strong> of the afternoon<br><strong>soqna</strong> we drove<br><strong>għal Ħ’Attard</strong> to Attard<br><strong>u żorna ftit</strong> and we visited for a while<br><strong>lin-nanna</strong> grandmother.</td></tr><tr><td>In-nanna Lina tatna biċċa kejk u qagħdet titkellem ftit magħna.</td><td>Grandmother Lina gave us a piece of cake and chatted with us for a while.<br><strong>In-nanna Lina</strong> grandmother Lina<br><strong>tatna</strong> she gave us, tat + na<br><strong>biċċa kejk</strong> a piece of cake<br><strong>u qagħdet titkellem ftit</strong> and she chatted for a while, a continued action<br><strong>magħna</strong> with us.</td></tr><tr><td>Wara morna lura d-dar għax konna għajjenin.</td><td>Afterwards we went back home because we were tired.<br><strong>Wara</strong> afterwards<br><strong>morna lura d-dar</strong> we went back home<br><strong>għax</strong> because<br><strong>konna għajjenin</strong> we were tired, plural.</td></tr><tr><td>Sakemm wasalna d-dar, oħti raqdet fuq spallti waqt li jien qgħadt inħares ’il barra mit-tieqa nosserva t-toroq.</td><td>On the way home my sister fell asleep on my shoulder while I kept looking out of the window, watching the streets.<br><strong>Sakemm wasalna d-dar</strong> until we got home<br><strong>oħti raqdet</strong> my sister slept<br><strong>fuq spallti</strong> on my shoulder, the possessive form of spalla<br><strong>waqt li jien</strong> while I<br><strong>qgħadt inħares</strong> I kept looking, not literally &quot;I sat&quot;<br><strong>’il barra mit-tieqa</strong> out of the window<br><strong>nosserva t-toroq</strong> I observe the streets.</td></tr><tr><td>Rajt ħafna karozzi u nies għaddejjin, però l-iktar ħaġa li laqtitni kienet villa kbira u lussuża.</td><td>I saw many cars and people passing, but what struck me most was a large, luxurious villa.<br><strong>Rajt</strong> I saw<br><strong>ħafna karozzi</strong> many cars<br><strong>u nies għaddejjin</strong> and people passing<br><strong>però</strong> but<br><strong>l-iktar ħaġa li laqtitni</strong> the thing that struck me most<br><strong>kienet</strong> it was<br><strong>villa kbira u lussuża</strong> a large, luxurious villa, feminine.</td></tr><tr><td>Kellha grada kbira kulur id-deheb u ħafna twieqi mal-faċċata.</td><td>It had a large golden gate and many windows along the front.<br><strong>Kellha</strong> it had, past feminine, referring to villa<br><strong>grada kbira</strong> a large gate<br><strong>kulur id-deheb</strong> gold-coloured; not necessarily made of gold<br><strong>u ħafna twieqi</strong> and many windows<br><strong>mal-faċċata</strong> along the façade.</td></tr><tr><td>Quddiemha kien hemm żewġ karozzi moderni, waħda ħamra u l-oħra bajda.</td><td>In front of it there were two modern cars, one red and the other white.<br><strong>Quddiemha</strong> in front of it, -ha referring to the villa<br><strong>kien hemm</strong> there were<br><strong>żewġ karozzi moderni</strong> two modern cars, plural<br><strong>waħda ħamra</strong> one red, feminine with karozza<br><strong>u l-oħra bajda</strong> and the other white.</td></tr></tbody></table><h3 id="the-narrative-order" tabindex="-1">The narrative order <a class="header-anchor" href="#the-narrative-order" aria-label="Permalink to &quot;The narrative order&quot;">​</a></h3><p>Sunday morning they set off → Żurrieq, the sea, the valley and Filfla → Siġġiewi for Mass → Dingli for lunch and a walk along the cliff → about three in the afternoon to Attard to visit Lina → on the way home they saw the villa. The text does not say the colour of the family&#39;s own car, and it does not say that the villa is Sara&#39;s home.</p><hr><h2 id="_15-nine-reading-questions-full-model-answers" tabindex="-1">15 Nine Reading Questions: Full Model Answers <a class="header-anchor" href="#_15-nine-reading-questions-full-model-answers" aria-label="Permalink to &quot;15 Nine Reading Questions: Full Model Answers&quot;">​</a></h2><h3 id="part-a-answer-the-questions" tabindex="-1">Part A: answer the questions <a class="header-anchor" href="#part-a-answer-the-questions" aria-label="Permalink to &quot;Part A: answer the questions&quot;">​</a></h3><p><code>A. Wieġeb</code> = part A: answer; <strong>Wieġeb</strong> is the imperative &quot;answer&quot;.</p><table tabindex="0"><thead><tr><th>Question and answer</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Meta ħarġet mal-familja tagħha Sara? — Sara ħarġet mal-familja tagħha nhar il-Ħadd li għadda.</td><td>When did Sara go out with her family? — Last Sunday.<br><strong>Meta</strong> when<br><strong>ħarġet</strong> she went out<br><strong>mal-familja tagħha</strong> with her family<br><strong>Sara</strong> the name<br><strong>nhar il-Ħadd li għadda</strong> last Sunday.</td></tr><tr><td>2. Kif kien it-temp dakinhar? — Dakinhar kienet xemx tisreġ u kien hemm ħafna sħana.</td><td>What was the weather like that day? — Blazing sun and very hot.<br><strong>Kif kien it-temp</strong> what the weather was like<br><strong>dakinhar</strong> that day<br><strong>kienet xemx tisreġ</strong> the sun was blazing<br><strong>u kien hemm</strong> and there was<br><strong>ħafna sħana</strong> a lot of heat.</td></tr><tr><td>3. X’libset Sara? — Sara libset libsa ħafifa u żanżnet sandli ġdid.</td><td>What did Sara wear? — A light dress, and she wore new sandals for the first time.<br><strong>X’libset</strong> what she wore<br><strong>Sara libset</strong> Sara put on<br><strong>libsa ħafifa</strong> a light dress<br><strong>u żanżnet</strong> and she wore for the first time, third person feminine past<br><strong>sandli ġdid</strong> new sandals, following the text.</td></tr><tr><td>4. X’kulur kienet il-qmis ta’ missier Sara? — Il-qmis ta’ missier Sara kienet safra.</td><td>What colour was Sara&#39;s father&#39;s shirt? — Yellow.<br><strong>X’kulur</strong> what colour<br><strong>kienet</strong> it was, feminine<br><strong>il-qmis</strong> the shirt<br><strong>ta’ missier Sara</strong> of Sara&#39;s father<br><strong>safra</strong> yellow, feminine.</td></tr><tr><td>5. Fi x’ħin telqu mid-dar? — Telqu mid-dar fl-għaxra ta’ filgħodu.</td><td>At what time did they leave the house? — At ten in the morning.<br><strong>Fi x’ħin</strong> at what time<br><strong>telqu</strong> they left<br><strong>mid-dar</strong> from the house<br><strong>fl-għaxra</strong> at ten<br><strong>ta’ filgħodu</strong> of the morning.</td></tr><tr><td>6. Semmi tliet postijiet li marru fihom il-familja ta’ Sara. — Il-familja marret iż-Żurrieq biex tara l-veduta, is-Siġġiewi għall-quddies u Ħad-Dingli għall-ikla ta’ nofsinhar.</td><td>Name three places Sara&#39;s family went to. — Żurrieq for the view, Siġġiewi for Mass and Dingli for lunch.<br><strong>Semmi</strong> name<br><strong>tliet postijiet</strong> three places<br><strong>li marru fihom</strong> that they went to<br><strong>il-familja ta’ Sara</strong> Sara&#39;s family<br><strong>Il-familja marret</strong> the family went, a collective noun taking a singular<br><strong>iż-Żurrieq</strong> a place name<br><strong>biex tara l-veduta</strong> in order to see the view<br><strong>is-Siġġiewi għall-quddies</strong> to Siġġiewi for Mass<br><strong>u Ħad-Dingli għall-ikla ta’ nofsinhar</strong> and to Dingli for the midday meal.</td></tr><tr><td>7. X’kielet Sara u għaliex bdiet tidħak biha oħtha? — Sara kielet għaġin biż-zalza ħamra. Oħtha bdiet tidħak biha għax ċappset il-libsa biż-zalza.</td><td>What did Sara eat and why did her sister laugh at her? — Pasta with red sauce; her sister laughed because she stained her dress with the sauce.<br><strong>X’kielet</strong> what she ate<br><strong>u għaliex</strong> and why<br><strong>bdiet tidħak biha</strong> she began laughing at her<br><strong>oħtha</strong> her sister<br><strong>għaġin biż-zalza ħamra</strong> pasta with red sauce<br><strong>għax ċappset</strong> because she stained<br><strong>il-libsa biż-zalza</strong> the dress with the sauce.</td></tr><tr><td>8. X’jisimha n-nanna ta’ Sara u x’tathom meta marru jarawha? — In-nanna ta’ Sara jisimha Lina u tathom biċċa kejk meta marru jarawha.</td><td>What is Sara&#39;s grandmother called and what did she give them when they visited? — Lina, and she gave them a piece of cake.<br><strong>X’jisimha</strong> what she is called<br><strong>n-nanna ta’ Sara</strong> Sara&#39;s grandmother<br><strong>u x’tathom</strong> and what she gave them<br><strong>meta marru jarawha</strong> when they went to see her<br><strong>jisimha Lina</strong> she is called Lina<br><strong>u tathom biċċa kejk</strong> and she gave them a piece of cake; tat + hom.</td></tr><tr><td>9. Fi kliemek iddeskrivi l-villa li rat Sara u l-karozzi li kien hemm quddiemha. — Sara rat villa kbira u lussuża, bi grada kbira kulur id-deheb u ħafna twieqi fuq il-faċċata. Quddiem il-villa kien hemm żewġ karozzi moderni, waħda ħamra u l-oħra bajda.</td><td>In your own words describe the villa Sara saw and the cars in front of it. — A large, luxurious villa with a golden gate and many windows on the front; in front of it two modern cars, one red and one white.<br><strong>Fi kliemek</strong> in your own words<br><strong>iddeskrivi</strong> describe<br><strong>l-villa li rat Sara</strong> the villa Sara saw<br><strong>u l-karozzi</strong> and the cars<br><strong>li kien hemm quddiemha</strong> that were in front of it<br><strong>Sara rat</strong> Sara saw<br><strong>villa kbira u lussuża</strong> a large, luxurious villa<br><strong>bi grada kbira</strong> with a large gate<br><strong>kulur id-deheb</strong> gold-coloured<br><strong>u ħafna twieqi fuq il-faċċata</strong> and many windows on the front<br><strong>Quddiem il-villa</strong> in front of the villa<br><strong>kien hemm żewġ karozzi moderni</strong> there were two modern cars<br><strong>waħda ħamra u l-oħra bajda</strong> one red and the other white.</td></tr></tbody></table><hr><h2 id="_16-ten-true-or-false-items" tabindex="-1">16 Ten True or False Items <a class="header-anchor" href="#_16-ten-true-or-false-items" aria-label="Permalink to &quot;16 Ten True or False Items&quot;">​</a></h2><h3 id="statements-verdicts-and-corrections" tabindex="-1">Statements, verdicts and corrections <a class="header-anchor" href="#statements-verdicts-and-corrections" aria-label="Permalink to &quot;Statements, verdicts and corrections&quot;">​</a></h3><p><code>B. Wieġeb V jekk veru jew F jekk falz. Meta t-tweġiba tkun falz, irranġaha tajba taħtha</code> = write V if true or F if false; when the answer is false, correct it underneath.</p><p><strong>Wieġeb</strong> answer<br><strong>V / veru</strong> true / correct<br><strong>F / falz</strong> false / wrong<br><strong>jekk</strong> if<br><strong>jew</strong> or<br><strong>Meta t-tweġiba tkun falz</strong> when the answer is false, following the textbook&#39;s wording<br><strong>irranġaha tajba</strong> correct it<br><strong>taħtha</strong> underneath it.</p><p>In this exercise &quot;F&quot; sometimes carries the meaning &quot;not supported by the text&quot;; when reading, state the reason separately and do not invent colours, pets or homes that are not written.</p><table tabindex="0"><thead><tr><th>Item, verdict and correction</th><th>Chinese and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Fil-familja ta’ Sara hemm erba’ persuni. — <strong>V, for the four people on this outing as the item intends. Strictly speaking the total size of the family is not fully stated.</strong><br>More careful: F’din il-ħarġa kien hemm Sara, oħtha, ommha u missierha.</td><td>Sara&#39;s family has four people. — The text describes four people on the outing; it does not prove there are no other relatives.<br><strong>Fil-familja ta’ Sara</strong> in Sara&#39;s family<br><strong>hemm</strong> there are<br><strong>erba’ persuni</strong> four people<br><strong>F’din il-ħarġa</strong> on this outing<br><strong>kien hemm</strong> there were<br><strong>Sara, oħtha, ommha u missierha</strong> Sara, her sister, her mother and her father.</td></tr><tr><td>2. Oħt Sara libset flokk bil-komma qasira u qalziet aħmar. — <strong>F</strong>.<br>Oħt Sara libset flokk abjad bil-komma qasira u qalziet <strong>blu</strong>.</td><td>Sara&#39;s sister wore a short-sleeved top and red trousers. — False: white short sleeves and blue trousers.<br><strong>Oħt Sara</strong> Sara&#39;s sister<br><strong>libset</strong> she put on<br><strong>flokk bil-komma qasira</strong> a short-sleeved top<br><strong>u qalziet aħmar</strong> and red trousers<br><strong>abjad</strong> white, the detail added from the text<br><strong>blu</strong> blue, the point of the correction.</td></tr><tr><td>3. Omm Sara libset qmis roża u qalziet iswed. — <strong>F</strong>.<br>Omm Sara libset <strong>blaws roża u dublett iswed sal-irkoppa</strong>.</td><td>Sara&#39;s mother wore a pink shirt and black trousers. — False: a pink blouse and a black knee-length skirt.<br><strong>Omm Sara</strong> Sara&#39;s mother<br><strong>libset</strong> she put on<br><strong>qmis roża</strong> a pink shirt, the wording of the item<br><strong>u qalziet iswed</strong> and black trousers<br><strong>blaws roża</strong> a pink blouse, the original<br><strong>dublett iswed sal-irkoppa</strong> a black knee-length skirt.</td></tr><tr><td>4. Il-karozza tal-papà ta’ Sara hija ħadra. — <strong>Not mentioned; if a choice must be made, F = not supported by the text.</strong><br>Is-silta ma tgħidx x’kulur għandha l-karozza tal-papà ta’ Sara.</td><td>Sara&#39;s father&#39;s car is green. — There is no colour information; it cannot be changed to red, white or black.<br><strong>Il-karozza</strong> the car<br><strong>tal-papà ta’ Sara</strong> of Sara&#39;s father<br><strong>hija ħadra</strong> is green<br><strong>Is-silta ma tgħidx</strong> the passage does not say<br><strong>x’kulur għandha</strong> what colour it has<br><strong>l-karozza tal-papà ta’ Sara</strong> Sara&#39;s father&#39;s car.</td></tr><tr><td>5. Sara għandha kelba jisimha Filfla. — <strong>F, the item confuses the island name; whether she keeps a dog is not stated.</strong><br>Fis-silta, Filfla hija gżira li raw minn iż-Żurrieq; ma jissemmiex kelb ta’ Sara.</td><td>Sara has a female dog called Filfla. — In the passage Filfla is an island, not a pet that appears in the text.<br><strong>Sara għandha</strong> Sara has<br><strong>kelba</strong> a female dog<br><strong>jisimha Filfla</strong> it is called Filfla<br><strong>Fis-silta</strong> in the passage<br><strong>Filfla hija gżira</strong> Filfla is an island<br><strong>li raw minn iż-Żurrieq</strong> that they saw from Żurrieq<br><strong>ma jissemmiex kelb ta’ Sara</strong> Sara&#39;s dog is not mentioned; this is not a claim that she has none.</td></tr><tr><td>6. Sara u oħtha kielu għaġin biż-zalza bajda. — <strong>F</strong>.<br>Sara u oħtha kielu għaġin biż-zalza <strong>ħamra</strong>.</td><td>The two sisters ate pasta with white sauce. — False: red sauce.<br><strong>Sara u oħtha</strong> Sara and her sister<br><strong>kielu</strong> they ate<br><strong>għaġin</strong> pasta<br><strong>biż-zalza bajda</strong> with white sauce<br><strong>ħamra</strong> red, feminine with zalza.</td></tr><tr><td>7. In-nanna ta’ Sara jisimha Rożi. — <strong>F</strong>.<br>In-nanna ta’ Sara jisimha <strong>Lina</strong>.</td><td>Sara&#39;s grandmother is called Rożi. — False: Lina.<br><strong>In-nanna ta’ Sara</strong> Sara&#39;s grandmother<br><strong>jisimha</strong> she is called<br><strong>Rożi / Lina</strong> two female names.</td></tr><tr><td>8. In-nanna ta’ Sarah toqgħod Ħ’Attard. — <strong>V, on the natural reading that they visited her in Attard.</strong></td><td>The grandmother lives in Attard.<br><strong>In-nanna ta’ Sarah</strong> Sarah&#39;s grandmother; the item adds an h and refers to the same person<br><strong>toqgħod</strong> she lives<br><strong>Ħ’Attard</strong> the place name Attard<br><strong>Basis</strong> the text says they went to Attard to visit the grandmother; this is the inference the item expects.</td></tr><tr><td>9. Fit-triq lejn id-dar, Sara raqdet. — <strong>F</strong>.<br>Fit-triq lejn id-dar, <strong>oħt Sara</strong> raqdet fuq spallitha, waqt li Sara qagħdet tħares ’il barra mit-tieqa.</td><td>On the way home Sara slept. — False: her sister slept on her shoulder while Sara looked out of the window.<br><strong>Fit-triq lejn id-dar</strong> on the way home<br><strong>Sara raqdet</strong> Sara slept<br><strong>oħt Sara</strong> Sara&#39;s sister, the corrected subject<br><strong>fuq spallitha</strong> on her shoulder, here Sara&#39;s shoulder<br><strong>waqt li Sara</strong> while Sara<br><strong>qagħdet tħares</strong> she kept looking<br><strong>’il barra mit-tieqa</strong> out of the window.</td></tr><tr><td>10. Sara toqgħod ġo villa kbira u lussuża. — <strong>Not confirmed; for the item&#39;s purpose F.</strong><br>Sara rat villa kbira u lussuża mit-tieqa tal-karozza; is-silta ma tgħidx li tgħix fiha.</td><td>Sara lives in a large, luxurious villa. — The text only says she saw it on the way; it does not say she lives there.<br><strong>Sara toqgħod</strong> Sara lives<br><strong>ġo villa kbira u lussuża</strong> in a large, luxurious villa<br><strong>Sara rat</strong> Sara saw<br><strong>mit-tieqa tal-karozza</strong> from the car window<br><strong>is-silta ma tgħidx</strong> the passage does not say<br><strong>li tgħix fiha</strong> that she lives in it.</td></tr></tbody></table><h3 id="quick-answer-key" tabindex="-1">Quick answer key <a class="header-anchor" href="#quick-answer-key" aria-label="Permalink to &quot;Quick answer key&quot;">​</a></h3><p>As the exercise expects: <strong>1 V; 2 F; 3 F; 4 not mentioned (F when forced to choose); 5 F; 6 F; 7 F; 8 V; 9 F; 10 not confirmed (F for the item&#39;s purpose)</strong>. The inference limits for items 1, 5, 8 and 10 are in the table above; do not extend the simplified reading verdicts into facts the text does not state.</p>',130)])])}const m=r(o,[["render",s]]);export{u as __pageData,m as default};
